package com.groupmantcg;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/** Non-blocking memory/disk cache for the OSRS Wiki artwork referenced by the card catalog. */
@Slf4j
@Singleton
class CardArtService
{
	private static final int MEMORY_ENTRIES = 64;
	private static final String USER_AGENT = "Group-TCG RuneLite plugin";

	private final CardVisualCatalog catalog;
	private final GroupmanTcgConfig config;
	private final OkHttpClient http;
	private final Map<String, BufferedImage> memory = Collections.synchronizedMap(
		new LinkedHashMap<String, BufferedImage>(MEMORY_ENTRIES + 1, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
			{
				return size() > MEMORY_ENTRIES;
			}
		});
	private final Map<String, CompletableFuture<BufferedImage>> loading = new ConcurrentHashMap<>();
	private final Set<String> failed = ConcurrentHashMap.newKeySet();

	@Inject
	CardArtService(CardVisualCatalog catalog, GroupmanTcgConfig config, OkHttpClient http)
	{
		this.catalog = catalog;
		this.config = config;
		this.http = http;
	}

	BufferedImage getCached(String cardName)
	{
		CardVisualCatalog.CardVisual card = catalog.find(cardName);
		if (card == null || card.imageUrl().isEmpty())
		{
			return null;
		}
		String url = card.imageUrl();
		BufferedImage cached = memory.get(url);
		if (cached == null && config.downloadCardArt() && !failed.contains(url))
		{
			ensureLoad(url);
		}
		return cached;
	}

	void preload(Collection<String> cardNames)
	{
		if (cardNames != null)
		{
			for (String cardName : cardNames)
			{
				getCached(cardName);
			}
		}
	}

	private void ensureLoad(String url)
	{
		loading.computeIfAbsent(url, key -> CompletableFuture
			.supplyAsync(() -> load(key))
			.whenComplete((image, error) ->
			{
				if (image != null)
				{
					memory.put(key, image);
				}
				else
				{
					failed.add(key);
				}
				loading.remove(key);
			}));
	}

	private BufferedImage load(String url)
	{
		BufferedImage disk = readDisk(url);
		if (disk != null)
		{
			return disk;
		}
		if (!url.startsWith("https://oldschool.runescape.wiki/images/"))
		{
			return null;
		}
		try
		{
			Request request = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
			try (Response response = http.newCall(request).execute())
			{
				if (!response.isSuccessful() || response.body() == null)
				{
					return null;
				}
				try (InputStream input = response.body().byteStream())
				{
					BufferedImage image = ImageIO.read(input);
					if (image != null)
					{
						writeDisk(url, image);
					}
					return image;
				}
			}
		}
		catch (Exception ex)
		{
			log.debug("Unable to load optional card art", ex);
			return null;
		}
	}

	private BufferedImage readDisk(String url)
	{
		Path file = cacheFile(url);
		if (!Files.isRegularFile(file))
		{
			return null;
		}
		try (InputStream input = Files.newInputStream(file))
		{
			return ImageIO.read(input);
		}
		catch (Exception ex)
		{
			log.debug("Unable to read cached card art", ex);
			return null;
		}
	}

	private void writeDisk(String url, BufferedImage image)
	{
		Path target = cacheFile(url);
		Path temporary = target.resolveSibling(target.getFileName() + ".tmp");
		try
		{
			Files.createDirectories(target.getParent());
			try (OutputStream output = Files.newOutputStream(temporary))
			{
				ImageIO.write(image, "png", output);
			}
			try
			{
				Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (Exception ex)
		{
			log.debug("Unable to cache card art", ex);
		}
	}

	private static Path cacheFile(String url)
	{
		return Path.of(RuneLite.RUNELITE_DIR.getAbsolutePath(), "Groupman-TCG", "card-art-v1", sha256(url) + ".png");
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder output = new StringBuilder(digest.length * 2);
			for (byte part : digest)
			{
				output.append(String.format("%02x", part & 0xff));
			}
			return output.toString();
		}
		catch (Exception ex)
		{
			throw new IllegalStateException("Unable to hash card-art URL", ex);
		}
	}
}

package com.groupmantcg;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Base64;
import java.util.BitSet;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Deterministic compact representation of the bundled card catalog. */
@Singleton
class CardBitsetIndex
{
	private final List<String> cards;
	private final Map<String, Integer> indexes;
	private final String fingerprint;

	@Inject
	CardBitsetIndex(MonsterCardCatalog monsters, ItemCardCatalog items)
	{
		TreeSet<String> sorted = new TreeSet<>();
		monsters.entries().values().forEach(sorted::addAll);
		items.entries().values().forEach(sorted::addAll);
		cards = Collections.unmodifiableList(new ArrayList<>(sorted));

		Map<String, Integer> builtIndexes = new HashMap<>();
		for (int i = 0; i < cards.size(); i++)
		{
			builtIndexes.put(cards.get(i), i);
		}
		indexes = Collections.unmodifiableMap(builtIndexes);
		fingerprint = digest(String.join("\n", cards));
	}

	String encode(Set<String> owned)
	{
		BitSet bits = new BitSet(cards.size());
		for (String card : owned)
		{
			Integer index = indexes.get(card);
			if (index != null)
			{
				bits.set(index);
			}
		}
		return Base64.getEncoder().encodeToString(bits.toByteArray());
	}

	Set<String> decode(String encoded)
	{
		if (encoded == null)
		{
			throw new IllegalArgumentException("Missing bitset");
		}
		byte[] bytes = Base64.getDecoder().decode(encoded);
		if (bytes.length > (cards.size() + 7) / 8)
		{
			throw new IllegalArgumentException("Bitset exceeds catalog size");
		}
		BitSet bits = BitSet.valueOf(bytes);
		if (bits.length() > cards.size())
		{
			throw new IllegalArgumentException("Bitset contains an unknown index");
		}
		Set<String> decoded = new HashSet<>();
		for (int bit = bits.nextSetBit(0); bit >= 0; bit = bits.nextSetBit(bit + 1))
		{
			decoded.add(cards.get(bit));
		}
		return Collections.unmodifiableSet(decoded);
	}

	String fingerprint()
	{
		return fingerprint;
	}

	int size()
	{
		return cards.size();
	}

	private static String digest(String value)
	{
		try
		{
			byte[] bytes = MessageDigest.getInstance("SHA-256")
				.digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder result = new StringBuilder(bytes.length * 2);
			for (byte valueByte : bytes)
			{
				result.append(String.format("%02x", valueByte & 0xff));
			}
			return result.toString();
		}
		catch (Exception ex)
		{
			throw new IllegalStateException("Unable to fingerprint card catalog", ex);
		}
	}
}

package com.groupmantcg;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/** A requirement satisfied by owning any card in the group. */
final class CardRequirement
{
	private final List<String> displayNames;
	private final List<String> normalizedNames;
	private final String role;

	private CardRequirement(List<String> displayNames, List<String> normalizedNames, String role)
	{
		this.displayNames = Collections.unmodifiableList(displayNames);
		this.normalizedNames = Collections.unmodifiableList(normalizedNames);
		this.role = role;
	}

	static CardRequirement create(List<String> cards, String role)
	{
		if (cards == null)
		{
			return null;
		}
		List<String> display = new ArrayList<>();
		List<String> normalized = new ArrayList<>();
		for (String card : cards)
		{
			if (card != null && !card.trim().isEmpty())
			{
				display.add(card.trim());
				normalized.add(card.trim().toLowerCase(Locale.ROOT));
			}
		}
		if (display.isEmpty())
		{
			return null;
		}
		String cleanRole = role == null || role.trim().isEmpty()
			? null : role.trim().toLowerCase(Locale.ROOT);
		return new CardRequirement(display, normalized, cleanRole);
	}

	boolean isSatisfied(Set<String> owned)
	{
		for (String card : normalizedNames)
		{
			if (owned.contains(card))
			{
				return true;
			}
		}
		return false;
	}

	void addEveryMissing(Set<String> owned, List<String> missing)
	{
		for (int i = 0; i < normalizedNames.size(); i++)
		{
			if (!owned.contains(normalizedNames.get(i)))
			{
				missing.add(displayNames.get(i));
			}
		}
	}

	String display()
	{
		return String.join(" / ", displayNames);
	}

	String role()
	{
		return role;
	}

	boolean contains(String cardName)
	{
		return normalizedNames.contains(cardName.toLowerCase(Locale.ROOT));
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.awt.Color;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Minimal display metadata from OSRS TCG's public card catalog. */
@Slf4j
@Singleton
class CardVisualCatalog
{
	private final Map<String, CardVisual> cards;
	private final List<CardVisual> allCards;

	@Inject
	CardVisualCatalog(Gson gson)
	{
		Map<String, CardVisual> loaded = new LinkedHashMap<>();
		List<CardVisual> catalog = new ArrayList<>();
		try (InputStream input = getClass().getResourceAsStream("/osrs_tcg_cards.json"))
		{
			if (input != null)
			{
				SourceCard[] source = gson.fromJson(
					new InputStreamReader(input, StandardCharsets.UTF_8), SourceCard[].class);
				if (source != null)
				{
					for (SourceCard card : source)
					{
						if (card == null || card.name == null || card.name.trim().isEmpty())
						{
							continue;
						}
						String name = card.name.trim();
						boolean monster = isMonster(card.category);
						catalog.add(new CardVisual(name,
							card.imageUrl == null ? "" : card.imageUrl.trim(), monster,
							calculateScore(card.value, card.level, card.overrideScore, monster),
							card.examine == null ? "" : card.examine.trim(), card.value,
							primaryCategory(card.category)));
					}
					Map<String, RarityTier> tiers = displayTiers(catalog);
					for (CardVisual card : catalog)
					{
						card.rarity = tiers.getOrDefault(EntityCardCatalog.normalize(card.displayName),
							RarityTier.COMMON);
						loaded.put(EntityCardCatalog.normalize(card.displayName), card);
					}
				}
			}
		}
		catch (Exception ex)
		{
			log.warn("Unable to load OSRS TCG card visuals", ex);
		}
		cards = Collections.unmodifiableMap(loaded);
		allCards = Collections.unmodifiableList(new ArrayList<>(loaded.values()));
	}

	CardVisual find(String name)
	{
		return name == null ? null : cards.get(EntityCardCatalog.normalize(name));
	}

	List<CardVisual> all()
	{
		return allCards;
	}

	int size()
	{
		return cards.size();
	}

	static double calculateScore(Long value, Integer level, Long overrideScore, boolean monster)
	{
		double valueScore = value == null ? 0d : value.doubleValue();
		double levelScore;
		if (overrideScore != null)
		{
			levelScore = Math.max(0d, overrideScore.doubleValue());
		}
		else if (level == null)
		{
			levelScore = 0d;
		}
		else
		{
			levelScore = Math.pow(level.doubleValue(), 2d) * (monster ? 1.5d : 1d);
		}
		return Math.max(valueScore, levelScore);
	}

	private static boolean isMonster(List<String> categories)
	{
		if (categories == null)
		{
			return false;
		}
		for (String category : categories)
		{
			if ("monster".equalsIgnoreCase(category))
			{
				return true;
			}
		}
		return false;
	}

	private static String primaryCategory(List<String> categories)
	{
		if (categories == null || categories.isEmpty() || categories.get(0) == null)
		{
			return "unknown";
		}
		String[] parts = categories.get(0).split("&");
		String primary = parts.length == 0 ? "" : parts[0].trim();
		return primary.isEmpty() ? "unknown" : EntityCardCatalog.normalize(primary);
	}

	/**
	 * OSRS TCG's display-tier algorithm: percentiles per primary category,
	 * followed by equal-value/score unification and a global exact-value lift.
	 */
	private static Map<String, RarityTier> displayTiers(List<CardVisual> cards)
	{
		Map<String, RarityTier> result = new HashMap<>();
		Map<String, List<CardVisual>> byCategory = new HashMap<>();
		for (CardVisual card : cards)
		{
			byCategory.computeIfAbsent(card.primaryCategory, ignored -> new ArrayList<>()).add(card);
		}

		for (List<CardVisual> category : byCategory.values())
		{
			List<CardVisual> tiering = new ArrayList<>();
			for (CardVisual card : category)
			{
				if (lowValueExempt(card.value))
				{
					result.put(EntityCardCatalog.normalize(card.displayName), RarityTier.COMMON);
				}
				else
				{
					tiering.add(card);
				}
			}
			tiering.sort((left, right) -> Double.compare(left.score, right.score));
			Map<CardVisual, RarityTier> assigned = new HashMap<>();
			for (int i = 0; i < tiering.size(); i++)
			{
				double percentile = tiering.size() == 1 ? 1.0d : (double) i / (double) (tiering.size() - 1);
				assigned.put(tiering.get(i), tierForPercentile(percentile));
			}
			unifyCategoryTies(tiering, assigned);
			for (CardVisual card : tiering)
			{
				result.put(EntityCardCatalog.normalize(card.displayName),
					assigned.getOrDefault(card, RarityTier.COMMON));
			}
		}

		Map<Long, RarityTier> bestByValue = new HashMap<>();
		for (CardVisual card : cards)
		{
			if (card.value != null)
			{
				bestByValue.merge(card.value,
					result.getOrDefault(EntityCardCatalog.normalize(card.displayName), RarityTier.COMMON),
					CardVisualCatalog::bestTier);
			}
		}
		for (CardVisual card : cards)
		{
			String key = EntityCardCatalog.normalize(card.displayName);
			if (lowValueExempt(card.value))
			{
				result.put(key, RarityTier.COMMON);
			}
			else if (card.value != null)
			{
				result.put(key, bestByValue.getOrDefault(card.value, RarityTier.COMMON));
			}
		}
		return result;
	}

	private static void unifyCategoryTies(List<CardVisual> sorted, Map<CardVisual, RarityTier> assigned)
	{
		Map<Long, RarityTier> bestByValue = new HashMap<>();
		for (CardVisual card : sorted)
		{
			if (card.value != null)
			{
				bestByValue.merge(card.value, assigned.get(card), CardVisualCatalog::bestTier);
			}
		}
		for (CardVisual card : sorted)
		{
			if (card.value != null)
			{
				assigned.put(card, bestByValue.get(card.value));
			}
		}

		int index = 0;
		while (index < sorted.size())
		{
			int end = index + 1;
			long scoreKey = Math.round(sorted.get(index).score);
			while (end < sorted.size() && Math.round(sorted.get(end).score) == scoreKey)
			{
				end++;
			}
			RarityTier best = RarityTier.COMMON;
			for (int i = index; i < end; i++)
			{
				best = bestTier(best, assigned.get(sorted.get(i)));
			}
			for (int i = index; i < end; i++)
			{
				assigned.put(sorted.get(i), best);
			}
			index = end;
		}
	}

	private static boolean lowValueExempt(Long value)
	{
		return value != null && (value == 0L || value == 1L);
	}

	private static RarityTier tierForPercentile(double percentile)
	{
		if (percentile >= 0.98d) return RarityTier.GODLY;
		if (percentile >= 0.95d) return RarityTier.MYTHIC;
		if (percentile >= 0.90d) return RarityTier.LEGENDARY;
		if (percentile >= 0.75d) return RarityTier.EPIC;
		if (percentile >= 0.50d) return RarityTier.RARE;
		if (percentile >= 0.25d) return RarityTier.UNCOMMON;
		return RarityTier.COMMON;
	}

	private static RarityTier bestTier(RarityTier left, RarityTier right)
	{
		if (left == null) return right == null ? RarityTier.COMMON : right;
		if (right == null) return left;
		return left.ordinal() >= right.ordinal() ? left : right;
	}

	private enum RarityTier
	{
		COMMON("Common", new Color(0xFFFFFF)),
		UNCOMMON("Uncommon", new Color(0x2ECC71)),
		RARE("Rare", new Color(0x3498DB)),
		EPIC("Epic", new Color(0x9B59B6)),
		LEGENDARY("Legendary", new Color(0xE74C3C)),
		MYTHIC("Mythic", new Color(0xFF6EC7)),
		GODLY("Godly", new Color(0xF2C94C));

		private final String label;
		private final Color color;

		RarityTier(String label, Color color)
		{
			this.label = label;
			this.color = color;
		}
	}

	static final class CardVisual
	{
		private final String displayName;
		private final String imageUrl;
		private final boolean monster;
		private final double score;
		private final String examine;
		private final Long value;
		private final String primaryCategory;
		private RarityTier rarity = RarityTier.COMMON;

		private CardVisual(String displayName, String imageUrl, boolean monster, double score,
			String examine, Long value, String primaryCategory)
		{
			this.displayName = displayName;
			this.imageUrl = imageUrl;
			this.monster = monster;
			this.score = score;
			this.examine = examine;
			this.value = value;
			this.primaryCategory = primaryCategory;
		}

		String displayName() { return displayName; }
		String imageUrl() { return imageUrl; }
		boolean monster() { return monster; }
		double score() { return score; }
		String examine() { return examine; }
		Color rarityColor() { return rarity.color; }
		String rarityLabel() { return rarity.label; }
		long power() { return Math.round(score); }
	}

	private static final class SourceCard
	{
		private String name;
		private List<String> category;
		private String imageUrl;
		private Integer level;
		private Long value;
		private Long overrideScore;
		private String examine;
	}
}

package com.groupmantcg;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** The same seven-by-three card-face layout used by OSRS TCG's collection album. */
final class CollectionAlbumGridPanel extends JPanel
{
	static final int PAGE_SIZE = 21;
	private static final int COLS = 7;
	private static final int ROWS = 3;
	private static final int GAP = 5;
	private static final int QTY_LABEL_RESERVE_PX = 18;

	private final CardArtService art;
	private List<Slot> slots = Collections.emptyList();
	private List<Rectangle> lastCardBounds = Collections.emptyList();

	CollectionAlbumGridPanel(CardArtService art)
	{
		this.art = art;
		setOpaque(true);
		setBackground(new Color(0x1E1E1E));
		setMinimumSize(new Dimension(620, 340));
		setPreferredSize(new Dimension(980, 520));
		setToolTipText("");
	}

	void setSlots(List<Slot> next)
	{
		slots = next == null ? Collections.emptyList() : new ArrayList<>(next);
		repaint();
	}

	boolean hasVisibleFoilCards()
	{
		for (Slot slot : slots)
		{
			if (slot.ownership.foilCopies() > 0)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public String getToolTipText(java.awt.event.MouseEvent event)
	{
		if (event == null)
		{
			return null;
		}
		for (int i = 0; i < lastCardBounds.size() && i < slots.size(); i++)
		{
			Rectangle bounds = lastCardBounds.get(i);
			if (bounds.contains(event.getPoint()))
			{
				Slot slot = slots.get(i);
				CollectionAlbumSnapshot.Ownership owned = slot.ownership;
				if (owned.totalCopies() == 0)
				{
					return slot.card.displayName() + " - Missing";
				}
				return slot.card.displayName() + " - " + quantityDescription(owned);
			}
		}
		return null;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);
		Graphics2D g2 = (Graphics2D) graphics.create();
		List<Rectangle> paintedBounds = new ArrayList<>();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			Insets insets = getInsets();
			int innerWidth = Math.max(0, getWidth() - insets.left - insets.right);
			int innerHeight = Math.max(0, getHeight() - insets.top - insets.bottom);
			if (innerWidth <= 0 || innerHeight <= 0)
			{
				return;
			}
			if (slots.isEmpty())
			{
				g2.setColor(new Color(0xAAAAAA));
				g2.drawString("No cards match the current filters.", insets.left + 16, insets.top + 24);
				return;
			}

			int cellWidth = (innerWidth - (COLS - 1) * GAP) / COLS;
			int cellHeight = (innerHeight - (ROWS - 1) * GAP) / ROWS;
			int contentHeight = Math.max(1, cellHeight - QTY_LABEL_RESERVE_PX);
			double scale = Math.min(
				cellWidth / (double) OsrsTcgCardRenderer.DEFAULT_CARD_WIDTH,
				contentHeight / (double) OsrsTcgCardRenderer.DEFAULT_CARD_HEIGHT) * 0.94d;
			int cardWidth = Math.max(1, (int) Math.round(OsrsTcgCardRenderer.DEFAULT_CARD_WIDTH * scale));
			int cardHeight = Math.max(1, (int) Math.round(OsrsTcgCardRenderer.DEFAULT_CARD_HEIGHT * scale));

			for (int i = 0; i < slots.size() && i < PAGE_SIZE; i++)
			{
				int column = i % COLS;
				int row = i / COLS;
				int cellX = column * (cellWidth + GAP);
				int cellY = row * (cellHeight + GAP);
				int offsetX = cellX + (cellWidth - cardWidth) / 2;
				int offsetY = cellY + (contentHeight - cardHeight) / 2;
				Rectangle bounds = new Rectangle(insets.left + offsetX, insets.top + offsetY,
					cardWidth, cardHeight);
				paintedBounds.add(bounds);

				Slot slot = slots.get(i);
				boolean owned = slot.ownership.totalCopies() > 0;
				boolean foil = slot.ownership.foilCopies() > 0;
				BufferedImage image = art.getCached(slot.card.displayName());
				if (!owned)
				{
					g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.3f));
				}
				OsrsTcgCardRenderer.drawCardFace(g2, bounds, slot.card, foil,
					slot.card.rarityColor(), image, 0L, foil);
				if (!owned)
				{
					g2.setComposite(AlphaComposite.SrcOver);
				}

				String quantity = quantityLabel(slot.ownership);
				if (!quantity.isEmpty())
				{
					g2.setColor(new Color(0xDDDDDD));
					g2.setFont(FontManager.getRunescapeSmallFont());
					int textWidth = g2.getFontMetrics().stringWidth(quantity);
					int textX = insets.left + offsetX + (cardWidth - textWidth) / 2;
					int textY = insets.top + offsetY + cardHeight
						+ g2.getFontMetrics().getAscent() + 2;
					g2.drawString(quantity, textX, textY);
				}
			}
		}
		finally
		{
			g2.dispose();
			lastCardBounds = paintedBounds;
		}
	}

	private static String quantityLabel(CollectionAlbumSnapshot.Ownership owned)
	{
		return owned.totalCopies() > 1 ? quantityDescription(owned) : "";
	}

	private static String quantityDescription(CollectionAlbumSnapshot.Ownership owned)
	{
		if (owned.normalCopies() > 0 && owned.foilCopies() > 0)
		{
			return owned.foilCopies() + "x foil, " + owned.normalCopies() + "x normal";
		}
		if (owned.foilCopies() > 0)
		{
			return owned.foilCopies() + "x foil";
		}
		return owned.normalCopies() + "x normal";
	}

	static final class Slot
	{
		private final CardVisualCatalog.CardVisual card;
		private final CollectionAlbumSnapshot.Ownership ownership;

		Slot(CardVisualCatalog.CardVisual card, CollectionAlbumSnapshot.Ownership ownership)
		{
			this.card = card;
			this.ownership = ownership;
		}
	}
}

package com.groupmantcg;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;

/** Owns the single reusable full collection window. */
@Singleton
final class CollectionAlbumManager
{
	private final SharedCollectionService collections;
	private final CardVisualCatalog catalog;
	private final CardArtService art;

	private volatile CollectionAlbumWindow window;
	private String activeCollectionKey = "";
	private String activeDisplayName = "Shared collection";

	@Inject
	CollectionAlbumManager(SharedCollectionService collections, CardVisualCatalog catalog,
		CardArtService art)
	{
		this.collections = collections;
		this.catalog = catalog;
		this.art = art;
	}

	void show(String collectionKey, String displayName)
	{
		String key = collectionKey == null ? "" : collectionKey;
		String name = displayName == null ? "Shared collection" : displayName;
		SwingUtilities.invokeLater(() ->
		{
			activeCollectionKey = key;
			activeDisplayName = name;
			if (window == null || !window.isDisplayable())
			{
				window = new CollectionAlbumWindow(catalog, art);
			}
			window.showCollection(collections.collectionAlbum(key, name));
		});
	}

	void refreshIfVisible()
	{
		SwingUtilities.invokeLater(() ->
		{
			CollectionAlbumWindow current = window;
			if (current != null && current.isShowing())
			{
				current.refreshCollection(collections.collectionAlbum(
					activeCollectionKey, activeDisplayName));
			}
		});
	}

	void dispose()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (window != null)
			{
				window.disposeInternal();
				window = null;
			}
		});
	}
}

package com.groupmantcg;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/** Immutable ownership data used by the read-only full collection album. */
final class CollectionAlbumSnapshot
{
	private final String displayName;
	private final Set<String> ownedCards;
	private final Map<String, Ownership> ownership;

	CollectionAlbumSnapshot(String displayName, Set<String> ownedCards,
		Map<String, Ownership> ownership)
	{
		this.displayName = displayName == null || displayName.trim().isEmpty()
			? "Shared collection" : displayName.trim();
		this.ownedCards = Collections.unmodifiableSet(new HashSet<>(ownedCards));
		this.ownership = Collections.unmodifiableMap(new HashMap<>(ownership));
	}

	String displayName()
	{
		return displayName;
	}

	Set<String> ownedCards()
	{
		return ownedCards;
	}

	Ownership ownershipOf(String cardName)
	{
		String normalized = EntityCardCatalog.normalize(cardName);
		Ownership exact = ownership.get(normalized);
		if (exact != null)
		{
			return exact;
		}
		return ownedCards.contains(normalized) ? Ownership.ONE_NORMAL : Ownership.NONE;
	}

	static final class Ownership
	{
		private static final Ownership NONE = new Ownership(0, 0);
		private static final Ownership ONE_NORMAL = new Ownership(1, 0);

		private final int normalCopies;
		private final int foilCopies;

		Ownership(int normalCopies, int foilCopies)
		{
			this.normalCopies = Math.max(0, normalCopies);
			this.foilCopies = Math.max(0, foilCopies);
		}

		int normalCopies()
		{
			return normalCopies;
		}

		int foilCopies()
		{
			return foilCopies;
		}

		int totalCopies()
		{
			return normalCopies + foilCopies;
		}

		Ownership plus(Ownership other)
		{
			return other == null ? this
				: new Ownership(normalCopies + other.normalCopies, foilCopies + other.foilCopies);
		}
	}
}

package com.groupmantcg;

