package com.groupmantcg;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/** Immutable entity-name to OSRS TCG card-name index. */
@Slf4j
abstract class EntityCardCatalog
{
	private Map<String, Set<String>> cardsByEntity = Collections.emptyMap();

	EntityCardCatalog(Gson gson, String resource)
	{
		try (InputStream input = getClass().getResourceAsStream(resource))
		{
			if (input == null)
			{
				log.warn("Missing card catalog {}", resource);
				return;
			}
			Snapshot snapshot = gson.fromJson(new InputStreamReader(input, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.entityToCards == null)
			{
				return;
			}

			Map<String, Set<String>> loaded = new HashMap<>();
			for (Map.Entry<String, List<String>> entry : snapshot.entityToCards.entrySet())
			{
				if (entry.getKey() == null || entry.getValue() == null)
				{
					continue;
				}
				Set<String> variants = new HashSet<>();
				for (String card : entry.getValue())
				{
					if (card != null && !card.trim().isEmpty())
					{
						variants.add(normalize(card));
					}
				}
				if (!variants.isEmpty())
				{
					loaded.put(normalize(entry.getKey()), Collections.unmodifiableSet(variants));
				}
			}
			cardsByEntity = Collections.unmodifiableMap(loaded);
		}
		catch (Exception ex)
		{
			log.warn("Unable to load card catalog {}", resource, ex);
		}
	}

	Set<String> cardsFor(String entityName)
	{
		if (entityName == null)
		{
			return Collections.emptySet();
		}
		String normalized = normalize(entityName);
		Set<String> exact = cardsByEntity.get(normalized);
		if (exact != null)
		{
			return exact;
		}
		return cardsByEntity.getOrDefault(normalized.replaceFirst("\\([1-4]\\)$", ""), Collections.emptySet());
	}

	Map<String, Set<String>> entries()
	{
		return cardsByEntity;
	}

	int size()
	{
		return cardsByEntity.size();
	}

	static String normalize(String value)
	{
		return value.replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT);
	}

	private static class Snapshot
	{
		Map<String, List<String>> entityToCards;
	}
}

package com.groupmantcg;

import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

@Singleton
class FeedbackService
{
	private static final long THROTTLE_MILLIS = 900L;
	private static final int MAX_REQUIREMENTS = 5;
	private final GroupmanTcgConfig config;
	private final ChatMessageManager chat;
	private long lastMessageAt;

	@Inject
	FeedbackService(GroupmanTcgConfig config, ChatMessageManager chat)
	{
		this.config = config;
		this.chat = chat;
	}

	void locked(String target, List<String> requirements)
	{
		String prefix = target == null || target.isEmpty() ? "Action locked" : target + " is locked";
		send(prefix + ". Required: " + summarize(requirements));
	}

	void missing(List<String> requirements)
	{
		send("Action locked. Missing cards: " + summarize(requirements));
	}

	private void send(String message)
	{
		long now = System.currentTimeMillis();
		if (!config.chatFeedback() || now - lastMessageAt < THROTTLE_MILLIS)
		{
			return;
		}
		lastMessageAt = now;
		chat.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("[Group TCG] " + message)
			.build());
	}

	private static String summarize(List<String> requirements)
	{
		int shown = Math.min(requirements.size(), MAX_REQUIREMENTS);
		String result = String.join(", ", requirements.subList(0, shown));
		return requirements.size() > shown ? result + " and " + (requirements.size() - shown) + " more" : result;
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
class GroupCacheCodec
{
	private final Gson gson;

	@Inject
	GroupCacheCodec(Gson gson)
	{
		this.gson = gson;
	}

	String encode(String groupKey, String fingerprint, String bits, Map<String, String> memberBits)
	{
		Cache cache = new Cache();
		cache.schema = 2;
		cache.groupKey = groupKey;
		cache.catalogFingerprint = fingerprint;
		cache.unlockBits = bits;
		cache.memberUnlockBits = memberBits == null
			? Collections.emptyMap() : new HashMap<>(memberBits);
		return gson.toJson(cache);
	}

	Cache decode(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		Cache cache = gson.fromJson(json, Cache.class);
		if (cache == null || (cache.schema != 1 && cache.schema != 2))
		{
			return null;
		}
		if (cache.memberUnlockBits == null)
		{
			cache.memberUnlockBits = Collections.emptyMap();
		}
		return cache;
	}

	static class Cache
	{
		int schema;
		String groupKey;
		String catalogFingerprint;
		String unlockBits;
		Map<String, String> memberUnlockBits;
	}
}

package com.groupmantcg;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

@Singleton
class GroupPackRevealOverlay extends Overlay
{
	private static final int PADDING = 8;
	private static final int GAP = 6;
	private static final int HEADER_HEIGHT = 46;
	private static final int CARD_WIDTH = 96;
	private static final int CARD_HEIGHT = 139;
	private static final Color PANEL = new Color(17, 20, 24, 238);
	private static final Color PANEL_BORDER = new Color(184, 115, 51);
	private static final BufferedImage PACK_IMAGE = ImageUtil.loadImageResource(GroupPackRevealOverlay.class,
		"/osrs-tcg/Pack_Standard.png");

	private final GroupPackRevealService reveals;
	private final CardVisualCatalog visuals;
	private final CardArtService art;
	private final GroupmanTcgConfig config;

	@Inject
	GroupPackRevealOverlay(GroupPackRevealService reveals, CardVisualCatalog visuals, CardArtService art,
		GroupmanTcgConfig config)
	{
		this.reveals = reveals;
		this.visuals = visuals;
		this.art = art;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GroupPackRevealService.RevealView reveal = reveals.currentReveal();
		if (reveal == null || reveal.pulls().isEmpty())
		{
			return null;
		}

		int count = reveal.pulls().size();
		int logicalWidth = PADDING * 2 + CARD_WIDTH * count + GAP * Math.max(0, count - 1);
		int logicalHeight = HEADER_HEIGHT + CARD_HEIGHT + PADDING + 3;
		double scale = scaleFor(config.packRevealScale());
		int width = Math.max(1, (int) Math.round(logicalWidth * scale));
		int height = Math.max(1, (int) Math.round(logicalHeight * scale));
		Graphics2D copy = (Graphics2D) graphics.create();
		try
		{
			copy.scale(scale, scale);
			copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			copy.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			copy.setColor(PANEL);
			copy.fillRoundRect(0, 0, logicalWidth, logicalHeight, 12, 12);
			copy.setColor(PANEL_BORDER);
			copy.setStroke(new BasicStroke(1.5f));
			copy.drawRoundRect(0, 0, logicalWidth - 1, logicalHeight - 1, 12, 12);

			drawHeader(copy, logicalWidth, reveal.opener());
			for (int i = 0; i < count; i++)
			{
				int x = PADDING + i * (CARD_WIDTH + GAP);
				drawCard(copy, x, HEADER_HEIGHT, reveal.pulls().get(i));
			}

			int remaining = (int) Math.round((logicalWidth - 2)
				* reveal.remainingFraction(System.currentTimeMillis()));
			copy.setColor(new Color(232, 185, 92));
			copy.fillRoundRect(1, logicalHeight - 4, remaining, 3, 3, 3);
		}
		finally
		{
			copy.dispose();
		}
		return new Dimension(width, height);
	}

	static double scaleFor(int percent)
	{
		return Math.max(40, Math.min(125, percent)) / 100.0d;
	}

	private static void drawHeader(Graphics2D graphics, int width, String opener)
	{
		if (PACK_IMAGE != null)
		{
			drawContained(graphics, PACK_IMAGE, PADDING, 3, 17, 28);
		}
		Font font = FontManager.getRunescapeBoldFont();
		graphics.setFont(font);
		String title = headerText(opener);
		FontMetrics metrics = graphics.getFontMetrics();
		title = ellipsize(title, metrics, width - PADDING * 2);
		int x = (width - metrics.stringWidth(title)) / 2;
		int y = 22;
		graphics.setColor(new Color(0, 0, 0, 190));
		graphics.drawString(title, x + 1, y + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(title, x, y);
	}

	static String headerText(String updater)
	{
		return "Cards added to collection by " + (updater == null ? "" : updater.trim());
	}

	private void drawCard(Graphics2D graphics, int x, int y, GroupPackRevealService.Pull pull)
	{
		CardVisualCatalog.CardVisual visual = visuals.find(pull.cardName());
		if (visual == null)
		{
			graphics.setColor(new Color(35, 37, 41, 250));
			graphics.fillRoundRect(x, y, CARD_WIDTH, CARD_HEIGHT, 8, 8);
			drawPlaceholder(graphics, x, y, CARD_WIDTH, CARD_HEIGHT, pull.cardName());
			return;
		}

		OsrsTcgCardRenderer.drawCardFace(graphics, new Rectangle(x, y, CARD_WIDTH, CARD_HEIGHT), visual,
			pull.foil(), visual.rarityColor(), art.getCached(pull.cardName()));

		if (pull.newForCollection())
		{
			drawBadge(graphics, x + 4, y - 14, "NEW", new Color(45, 126, 72));
		}
		if (pull.foil())
		{
			drawBadgeRight(graphics, x + CARD_WIDTH - 4, y - 14, "FOIL", new Color(91, 93, 151));
		}

	}

	private static void drawContained(Graphics2D graphics, BufferedImage image, int x, int y, int width, int height)
	{
		double scale = Math.min((double) width / image.getWidth(), (double) height / image.getHeight());
		int drawnWidth = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int drawnHeight = Math.max(1, (int) Math.round(image.getHeight() * scale));
		graphics.drawImage(image, x + (width - drawnWidth) / 2, y + (height - drawnHeight) / 2,
			drawnWidth, drawnHeight, null);
	}

	private static void drawPlaceholder(Graphics2D graphics, int x, int y, int width, int height, String name)
	{
		String initial = name == null || name.isEmpty() ? "?" : name.substring(0, 1).toUpperCase();
		graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
		FontMetrics metrics = graphics.getFontMetrics();
		graphics.setColor(new Color(110, 110, 110));
		graphics.drawString(initial, x + (width - metrics.stringWidth(initial)) / 2,
			y + (height + metrics.getAscent() - metrics.getDescent()) / 2);
	}

	private static void drawBadge(Graphics2D graphics, int x, int y, String text, Color background)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 9f));
		FontMetrics metrics = graphics.getFontMetrics();
		int width = metrics.stringWidth(text) + 5;
		graphics.setColor(background);
		graphics.fillRoundRect(x, y, width, 12, 4, 4);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, x + 3, y + 10);
	}

	private static void drawBadgeRight(Graphics2D graphics, int right, int y, String text, Color background)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, 9f));
		FontMetrics metrics = graphics.getFontMetrics();
		int width = metrics.stringWidth(text) + 5;
		drawBadge(graphics, right - width, y, text, background);
	}

	private static String ellipsize(String text, FontMetrics metrics, int width)
	{
		if (text == null || metrics.stringWidth(text) <= width)
		{
			return text == null ? "" : text;
		}
		String suffix = "...";
		int length = text.length();
		while (length > 0 && metrics.stringWidth(text.substring(0, length) + suffix) > width)
		{
			length--;
		}
		return text.substring(0, length).trim() + suffix;
	}
}

package com.groupmantcg;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Detects local pack transactions and presents verified remote reveals. */
@Singleton
class GroupPackRevealService
{
	private static final int MAX_PULLS = 5;
	private static final int MAX_QUEUED_REVEALS = 4;
	private static final long COLLECTION_SETTLE_MILLIS = 2_000L;
	private static final long STATE_POLL_MILLIS = 1_000L;
	private static final long INCOMPLETE_PACK_TIMEOUT_MILLIS = 30_000L;
	private static final long ART_WARMUP_MILLIS = 750L;
	static final long REMOTE_REVEAL_DELAY_MILLIS = 15_000L;
	private static final long MAX_RECENT_PULL_AGE_MILLIS = 120_000L;

	private final GroupmanTcgConfig config;
	private final LocalCollection localCollection;
	private final HostedSyncService hostedSync;
	private final CardVisualCatalog visualCatalog;
	private final CardArtService cardArt;

	private final Deque<QueuedReveal> queue = new ArrayDeque<>();
	private final LinkedHashMap<String, Boolean> hostedEvents = new LinkedHashMap<>();
	private Map<String, LocalCollection.CardInstance> previousInstances = Collections.emptyMap();
	private long previousOpenedPacks;
	private long pendingReadAt = -1L;
	private long nextStatePollAt;
	private long incompletePackObservedAt = -1L;
	private boolean rebaseline;
	private boolean started;
	private RevealView active;

	@Inject
	GroupPackRevealService(GroupmanTcgConfig config, LocalCollection localCollection,
		HostedSyncService hostedSync, CardVisualCatalog visualCatalog, CardArtService cardArt)
	{
		this.config = config;
		this.localCollection = localCollection;
		this.hostedSync = hostedSync;
		this.visualCatalog = visualCatalog;
		this.cardArt = cardArt;
	}

	void start()
	{
		started = true;
		prime(localCollection.snapshot());
		nextStatePollAt = System.currentTimeMillis() + STATE_POLL_MILLIS;
	}

	synchronized void stop()
	{
		started = false;
		queue.clear();
		hostedEvents.clear();
		active = null;
		pendingReadAt = -1L;
		previousInstances = Collections.emptyMap();
		previousOpenedPacks = 0L;
		nextStatePollAt = 0L;
		incompletePackObservedAt = -1L;
	}

	synchronized void localStateChanged()
	{
		if (started)
		{
			pendingReadAt = System.currentTimeMillis() + COLLECTION_SETTLE_MILLIS;
		}
	}

	synchronized void inferredApiPack(OsrsTcgInteropService.InferredPack inferred)
	{
		if (!started || inferred == null || inferred.cards().isEmpty()
			|| inferred.cards().size() > MAX_PULLS || !config.broadcastPackReveals())
		{
			return;
		}
		List<Pull> pulls = new ArrayList<>(inferred.cards().size());
		for (OsrsTcgInteropService.CardDelta card : inferred.cards())
		{
			pulls.add(new Pull(card.displayName(), card.foil(), true, "", inferred.inferredAt()));
		}
		hostedSync.queueLocalPack(pulls);
	}

	synchronized void profileChanged()
	{
		queue.clear();
		hostedEvents.clear();
		active = null;
		rebaseline = true;
		pendingReadAt = System.currentTimeMillis() + 500L;
	}

	synchronized void onTick()
	{
		if (!started)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (pendingReadAt >= 0L && now >= pendingReadAt)
		{
			pendingReadAt = -1L;
			LocalCollection.Snapshot snapshot = localCollection.snapshot();
			if (rebaseline)
			{
				rebaseline = false;
				prime(snapshot);
			}
			else
			{
				detectAndBroadcast(snapshot, now);
			}
			nextStatePollAt = now + STATE_POLL_MILLIS;
		}
		else if (now >= nextStatePollAt)
		{
			// OSRS TCG 0.18 updates tcg.save for each collection change without updating
			// RuneLite profile configuration, so no ConfigChanged event is guaranteed.
			detectAndBroadcast(localCollection.snapshot(), now);
			nextStatePollAt = now + STATE_POLL_MILLIS;
		}
		advance(now);
	}

	synchronized RevealView currentReveal()
	{
		if (!config.showPackReveals())
		{
			queue.clear();
			active = null;
			return null;
		}
		long now = System.currentTimeMillis();
		advance(now);
		return active != null && now >= active.visibleAt() ? active : null;
	}

	private void detectAndBroadcast(LocalCollection.Snapshot snapshot, long now)
	{
		if (!snapshot.available())
		{
			return;
		}
		Map<String, LocalCollection.CardInstance> current = index(snapshot.instances());
		List<List<Pull>> detectedPacks = detectRecentPacks(
			previousOpenedPacks, previousInstances, snapshot, now);
		if (isIncompletePackWrite(previousOpenedPacks, snapshot, detectedPacks))
		{
			if (incompletePackObservedAt < 0L)
			{
				incompletePackObservedAt = now;
			}
			if (now - incompletePackObservedAt < INCOMPLETE_PACK_TIMEOUT_MILLIS)
			{
				// OSRS TCG persists the incremented pack counter before it atomically writes
				// the pulled card rows. Keep the old baseline until those rows are visible.
				return;
			}
		}
		incompletePackObservedAt = -1L;
		for (List<Pull> pulls : detectedPacks)
		{
			if (!pulls.isEmpty() && pulls.size() <= MAX_PULLS)
			{
				if (config.broadcastPackReveals())
				{
					hostedSync.queueLocalPack(pulls);
				}
			}
		}
		previousOpenedPacks = snapshot.openedPacks();
		previousInstances = current;
	}

	static boolean isIncompletePackWrite(long previousOpenedPacks, LocalCollection.Snapshot snapshot,
		List<List<Pull>> detectedPacks)
	{
		return snapshot != null && snapshot.available()
			&& snapshot.openedPacks() > previousOpenedPacks
			&& (detectedPacks == null || detectedPacks.isEmpty());
	}

	static List<List<Pull>> detectRecentPacks(long previousOpenedPacks,
		Map<String, LocalCollection.CardInstance> previousInstances,
		LocalCollection.Snapshot snapshot, long now)
	{
		if (snapshot == null || !snapshot.available() || snapshot.openedPacks() <= previousOpenedPacks)
		{
			return Collections.emptyList();
		}
		Set<String> namesBeforePack = new HashSet<>();
		for (LocalCollection.CardInstance old : previousInstances.values())
		{
			namesBeforePack.add(old.normalizedName());
		}

		Map<Long, List<LocalCollection.CardInstance>> instancesByTime = new LinkedHashMap<>();
		for (LocalCollection.CardInstance instance : snapshot.instances())
		{
			if (previousInstances.containsKey(instance.id()) || instance.pulledAt() <= 0L
				|| now - instance.pulledAt() > MAX_RECENT_PULL_AGE_MILLIS
				|| instance.pulledAt() - now > 5_000L)
			{
				continue;
			}
			instancesByTime.computeIfAbsent(instance.pulledAt(), ignored -> new ArrayList<>()).add(instance);
		}

		List<List<Pull>> packs = new ArrayList<>();
		for (List<LocalCollection.CardInstance> instances : instancesByTime.values())
		{
			List<Pull> pulls = new ArrayList<>(instances.size());
			for (LocalCollection.CardInstance instance : instances)
			{
				pulls.add(new Pull(instance.displayName(), instance.foil(),
					!namesBeforePack.contains(instance.normalizedName()), instance.id(), instance.pulledAt()));
			}
			for (LocalCollection.CardInstance instance : instances)
			{
				namesBeforePack.add(instance.normalizedName());
			}
			packs.add(pulls);
		}
		return packs;
	}

	synchronized void hostedReveal(String eventId, String opener, List<Pull> pulls,
		long openedAt, long receivedAt)
	{
		if (!started || !config.showPackReveals() || eventId == null || eventId.trim().isEmpty()
			|| opener == null || opener.trim().isEmpty() || pulls == null || pulls.isEmpty()
			|| pulls.size() > MAX_PULLS || hostedEvents.containsKey(eventId))
		{
			return;
		}
		List<Pull> safePulls = new ArrayList<>(pulls.size());
		List<String> artNames = new ArrayList<>(pulls.size());
		for (Pull pull : pulls)
		{
			if (pull == null || pull.cardName() == null)
			{
				return;
			}
			CardVisualCatalog.CardVisual card = visualCatalog.find(pull.cardName());
			if (card == null)
			{
				return;
			}
			safePulls.add(new Pull(card.displayName(), pull.foil(), pull.newForCollection()));
			artNames.add(card.displayName());
		}
		hostedEvents.put(eventId, Boolean.TRUE);
		while (hostedEvents.size() > 256)
		{
			hostedEvents.remove(hostedEvents.keySet().iterator().next());
		}
		enqueue(opener.trim(), safePulls, artNames,
			remoteRevealNotBefore(openedAt, receivedAt, System.currentTimeMillis()));
	}

	static long remoteRevealNotBefore(long openedAt, long receivedAt, long now)
	{
		long reliableEventTime = receivedAt > 0L ? receivedAt : (openedAt > 0L ? openedAt : now);
		return Math.max(reliableEventTime, openedAt) + REMOTE_REVEAL_DELAY_MILLIS;
	}

	private void enqueue(String opener, List<Pull> safePulls, List<String> artNames, long notBefore)
	{
		cardArt.preload(artNames);
		if (queue.size() >= MAX_QUEUED_REVEALS)
		{
			queue.removeFirst();
		}
		queue.addLast(new QueuedReveal(opener, safePulls, notBefore));
		if (active == null)
		{
			activateNext(System.currentTimeMillis());
		}
	}

	private void advance(long now)
	{
		if (active != null && now >= active.expiresAt())
		{
			active = null;
		}
		if (active == null)
		{
			activateNext(now);
		}
	}

	private void activateNext(long now)
	{
		QueuedReveal next = queue.peekFirst();
		if (next == null)
		{
			return;
		}
		if (now < next.notBefore)
		{
			return;
		}
		queue.removeFirst();
		long visibleAt = Math.max(next.notBefore, now + ART_WARMUP_MILLIS);
		long durationMillis = Math.max(3, Math.min(15, config.packRevealDuration())) * 1_000L;
		active = new RevealView(next.opener, next.pulls, visibleAt, visibleAt + durationMillis);
	}

	private void prime(LocalCollection.Snapshot snapshot)
	{
		previousOpenedPacks = snapshot.openedPacks();
		previousInstances = index(snapshot.instances());
	}

	private static Map<String, LocalCollection.CardInstance> index(List<LocalCollection.CardInstance> instances)
	{
		Map<String, LocalCollection.CardInstance> indexed = new HashMap<>();
		for (LocalCollection.CardInstance instance : instances)
		{
			indexed.put(instance.id(), instance);
		}
		return Collections.unmodifiableMap(indexed);
	}

	static final class Pull
	{
		private final String cardName;
		private final boolean foil;
		private final boolean newForCollection;
		private final String sourceInstanceId;
		private final long pulledAt;

		Pull(String cardName, boolean foil, boolean newForCollection)
		{
			this(cardName, foil, newForCollection, "", 0L);
		}

		Pull(String cardName, boolean foil, boolean newForCollection, String sourceInstanceId, long pulledAt)
		{
			this.cardName = cardName;
			this.foil = foil;
			this.newForCollection = newForCollection;
			this.sourceInstanceId = sourceInstanceId == null ? "" : sourceInstanceId;
			this.pulledAt = pulledAt;
		}

		String cardName() { return cardName; }
		boolean foil() { return foil; }
		boolean newForCollection() { return newForCollection; }
		String sourceInstanceId() { return sourceInstanceId; }
		long pulledAt() { return pulledAt; }
	}

	static final class RevealView
	{
		private final String opener;
		private final List<Pull> pulls;
		private final long visibleAt;
		private final long expiresAt;

		private RevealView(String opener, List<Pull> pulls, long visibleAt, long expiresAt)
		{
			this.opener = opener;
			this.pulls = Collections.unmodifiableList(new ArrayList<>(pulls));
			this.visibleAt = visibleAt;
			this.expiresAt = expiresAt;
		}

		String opener() { return opener; }
		List<Pull> pulls() { return pulls; }
		long visibleAt() { return visibleAt; }
		long expiresAt() { return expiresAt; }

		double remainingFraction(long now)
		{
			long duration = expiresAt - visibleAt;
			return duration <= 0L ? 0d : Math.max(0d, Math.min(1d, (double) (expiresAt - now) / duration));
		}
	}

	private static final class QueuedReveal
	{
		private final String opener;
		private final List<Pull> pulls;
		private final long notBefore;

		private QueuedReveal(String opener, List<Pull> pulls, long notBefore)
		{
			this.opener = opener;
			this.pulls = new ArrayList<>(pulls);
			this.notBefore = notBefore;
		}
	}
}

