@Slf4j
@PluginDescriptor(
	name = "Group TCG",
	description = "Use OSRS TCG cards as solo or shared Bronzeman unlocks",
	tags = {"tcg", "group", "bronzeman", "restriction", "multiplayer", "solo"}
)
public class GroupmanTcgPlugin extends Plugin
{
	@Inject
	private GroupmanTcgConfig config;
	@Inject
	private Client client;
	@Inject
	private SharedCollectionService collection;
	@Inject
	private MonsterCardCatalog monsters;
	@Inject
	private ItemCardCatalog items;
	@Inject
	private FeedbackService feedback;
	@Inject
	private SkillRestrictionEngine skillRestrictions;
	@Inject
	private LockedStateService lockedState;
	@Inject
	private ClientToolbar toolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private LockedNpcOverlay lockedNpcOverlay;
	@Inject
	private LockedGroundItemOverlay lockedGroundItemOverlay;
	@Inject
	private LockedWidgetItemOverlay lockedWidgetItemOverlay;
	@Inject
	private GroupPackRevealService packReveals;
	@Inject
	private HostedSyncService hostedSync;
	@Inject
	private GroupPackRevealOverlay packRevealOverlay;
	@Inject
	private TopTrumpsService topTrumps;
	@Inject
	private TopTrumpsOverlay topTrumpsOverlay;
	@Inject
	private CollectionAlbumManager collectionAlbums;
	@Inject
	private CardVisualCatalog cardVisuals;
	@Inject
	private OsrsTcgInteropService osrsTcgInterop;

	private GroupmanTcgPanel panel;
	private NavigationButton navigation;
	private int panelTicks;

	@Override
	protected void startUp()
	{
		osrsTcgInterop.start();
		collection.start();
		hostedSync.start();
		packReveals.start();
		topTrumps.start();
		panel = new GroupmanTcgPanel(collection, hostedSync, topTrumps, collectionAlbums,
			monsters, items, cardVisuals);
		navigation = NavigationButton.builder()
			.tooltip("Group TCG")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		toolbar.addNavigation(navigation);
		overlayManager.add(lockedNpcOverlay);
		overlayManager.add(lockedGroundItemOverlay);
		overlayManager.add(lockedWidgetItemOverlay);
		overlayManager.add(packRevealOverlay);
		overlayManager.add(topTrumpsOverlay);
		log.info("Group TCG started with {} NPCs and {} items", monsters.size(), items.size());
	}

	@Override
	protected void shutDown()
	{
		collectionAlbums.dispose();
		packReveals.stop();
		topTrumps.stop();
		hostedSync.stop();
		collection.stop();
		osrsTcgInterop.stop();
		overlayManager.remove(lockedNpcOverlay);
		overlayManager.remove(lockedGroundItemOverlay);
		overlayManager.remove(lockedWidgetItemOverlay);
		overlayManager.remove(packRevealOverlay);
		overlayManager.remove(topTrumpsOverlay);
		if (navigation != null)
		{
			toolbar.removeNavigation(navigation);
		}
		navigation = null;
		panel = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		osrsTcgInterop.onTick();
		collection.onTick();
		packReveals.onTick();
		hostedSync.onTick();
		topTrumps.onTick();
		if (++panelTicks % 5 == 0)
		{
			collectionAlbums.refreshIfVisible();
			GroupmanTcgPanel currentPanel = panel;
			SwingUtilities.invokeLater(() ->
			{
				if (currentPanel != null && currentPanel.isShowing())
				{
					currentPanel.refresh();
				}
			});
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		collection.contextChanged();
		hostedSync.contextChanged();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage event)
	{
		if (osrsTcgInterop.accept(event))
		{
			packReveals.inferredApiPack(osrsTcgInterop.drainInferredPack());
			collection.localCollectionChanged();
			hostedSync.localCollectionChanged();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("osrstcg".equals(event.getGroup()) && "state".equals(event.getKey()))
		{
			collection.localCollectionChanged();
			packReveals.localStateChanged();
			hostedSync.localCollectionChanged();
		}
		else if (GroupmanTcgConfig.GROUP.equals(event.getGroup())
			&& "collectionMode".equals(event.getKey()))
		{
			collection.contextChanged();
			hostedSync.collectionModeChanged();
		}
		else if (GroupmanTcgConfig.GROUP.equals(event.getGroup())
			&& "hostedSyncEnabled".equals(event.getKey()))
		{
			hostedSync.contextChanged();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		osrsTcgInterop.profileChanged();
		collection.profileChanged();
		packReveals.profileChanged();
		hostedSync.profileChanged();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry source = event.getMenuEntry();
		Player player = source.getPlayer();
		if (!isPlayerMenuAction(source.getType()) || player == null || player.getName() == null
			|| !topTrumps.canChallenge(player.getName()))
		{
			return;
		}
		for (MenuEntry existing : client.getMenuEntries())
		{
			if (TopTrumpsService.MENU_OPTION.equals(existing.getOption()))
			{
				return;
			}
		}
		String playerName = player.getName();
		client.createMenuEntry(-1)
			.setOption(TopTrumpsService.MENU_OPTION)
			.setTarget(source.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(ignored -> topTrumps.challenge(playerName));
	}

	private static boolean isPlayerMenuAction(MenuAction type)
	{
		return type == MenuAction.PLAYER_FIRST_OPTION || type == MenuAction.PLAYER_SECOND_OPTION
			|| type == MenuAction.PLAYER_THIRD_OPTION || type == MenuAction.PLAYER_FOURTH_OPTION
			|| type == MenuAction.PLAYER_FIFTH_OPTION || type == MenuAction.PLAYER_SIXTH_OPTION
			|| type == MenuAction.PLAYER_SEVENTH_OPTION || type == MenuAction.PLAYER_EIGHTH_OPTION
			|| type == MenuAction.RUNELITE_PLAYER;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (lockedState.restrictionsBypassed())
		{
			return;
		}
		SkillRestrictionEngine.Decision skillDecision = skillRestrictions.handle(event);
		if (skillDecision == SkillRestrictionEngine.Decision.BLOCKED)
		{
			return;
		}
		MenuEntry entry = event.getMenuEntry();
		NPC npc = entry.getNpc();
		if (npc != null && blockNpc(event, entry, npc))
		{
			return;
		}
		if (skillDecision == SkillRestrictionEngine.Decision.ALLOWED)
		{
			return;
		}
		blockItem(event, entry);
	}

	private boolean blockNpc(MenuOptionClicked event, MenuEntry entry, NPC npc)
	{
		LockedStateService.Requirement lock = lockedState.npcLock(npc);
		if (lock == null)
		{
			return false;
		}

		String option = clean(entry.getOption());
		if ("examine".equals(option))
		{
			return false;
		}
		MenuAction type = entry.getType();
		boolean targeted = type == MenuAction.ITEM_USE_ON_NPC || type == MenuAction.WIDGET_TARGET_ON_NPC;
		boolean combatAction = "attack".equals(option) || targeted;
		if (!(config.restrictAllNpcInteractions() || (config.restrictCombat() && combatAction)))
		{
			return false;
		}

		event.consume();
		feedback.locked(lock.target(), new java.util.ArrayList<>(lock.cards()));
		return true;
	}

	private void blockItem(MenuOptionClicked event, MenuEntry entry)
	{
		if (!config.restrictItems())
		{
			return;
		}
		String option = clean(entry.getOption());
		LockedStateService.Requirement lock = clickedItemLock(event, entry, option);
		if (lock == null)
		{
			return;
		}

		if ("examine".equals(option) || "drop".equals(option) || "destroy".equals(option)
			|| (config.allowBankDeposits() && option.startsWith("deposit")))
		{
			return;
		}
		event.consume();
		feedback.locked(lock.target(), new java.util.ArrayList<>(lock.cards()));
	}

	private LockedStateService.Requirement clickedItemLock(MenuOptionClicked event, MenuEntry entry,
		String option)
	{
		MenuAction action = event.getMenuAction();
		if (isGroundItemAcquisition(action, option))
		{
			// Ground-item menu entries expose the item through their identifier, not itemId.
			return lockedState.itemLock(event.getId());
		}

		int interfaceGroup = WidgetUtil.componentToInterface(entry.getParam1());
		if (isShopPurchase(action, interfaceGroup, option))
		{
			// Most shop entries expose itemId; name fallback covers alternate shop widgets.
			int itemId = entry.getItemId();
			return itemId > 0
				? lockedState.itemLock(itemId)
				: lockedState.itemLock(Text.removeTags(entry.getTarget()).trim());
		}
		if (isGrandExchangeSearchOperation(action, interfaceGroup, isGrandExchangeOpen()))
		{
			// GE search results are chatbox widgets and expose only the result's target text.
			return lockedState.itemLock(Text.removeTags(entry.getTarget()).trim());
		}

		return lockedState.itemLock(entry.getItemId());
	}

	static boolean isGroundItemAcquisition(MenuAction action, String option)
	{
		if (action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM)
		{
			return true;
		}
		if (!"take".equals(option))
		{
			return false;
		}
		return action == MenuAction.GROUND_ITEM_FIRST_OPTION
			|| action == MenuAction.GROUND_ITEM_SECOND_OPTION
			|| action == MenuAction.GROUND_ITEM_THIRD_OPTION
			|| action == MenuAction.GROUND_ITEM_FOURTH_OPTION
			|| action == MenuAction.GROUND_ITEM_FIFTH_OPTION;
	}

	static boolean isShopPurchase(MenuAction action, int interfaceGroup, String option)
	{
		return LockedWidgetItemOverlay.isShopInterface(interfaceGroup)
			&& option.startsWith("buy")
			&& (action == MenuAction.CC_OP || action == MenuAction.CC_OP_LOW_PRIORITY);
	}

	static boolean isGrandExchangeSearchOperation(MenuAction action, int interfaceGroup,
		boolean grandExchangeOpen)
	{
		return grandExchangeOpen && interfaceGroup == InterfaceID.CHATBOX
			&& (action == MenuAction.CC_OP || action == MenuAction.CC_OP_LOW_PRIORITY);
	}

	private boolean isGrandExchangeOpen()
	{
		return client.getWidget(InterfaceID.GE_OFFERS, 0) != null;
	}

	private static String clean(String text)
	{
		return Text.removeTags(text == null ? "" : text).trim().toLowerCase(Locale.ROOT);
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(184, 115, 51));
		graphics.fillOval(1, 1, 22, 22);
		graphics.setColor(new Color(49, 39, 32));
		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 15));
		graphics.drawString("G", 7, 18);
		graphics.dispose();
		return image;
	}

	@Provides
	GroupmanTcgConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroupmanTcgConfig.class);
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Synchronous API adapter. Callers run it only on RuneLite's background executor. */
@Singleton
class HostedApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;
	private final Gson gson;
	private final GroupmanTcgConfig config;
	private final HttpUrl fixedBaseUrl;

	@Inject
	HostedApiClient(OkHttpClient http, Gson gson, GroupmanTcgConfig config)
	{
		this.http = http;
		this.gson = gson;
		this.config = config;
		this.fixedBaseUrl = null;
	}

	HostedApiClient(OkHttpClient http, Gson gson, String baseUrl)
	{
		this.http = http;
		this.gson = gson;
		this.config = null;
		this.fixedBaseUrl = parseBaseUrl(baseUrl);
	}

	CreateResponse createGroup(String setupKey, String playerName, String collectionMode) throws IOException
	{
		return createGroupAt(configuredBaseUrl(), setupKey, playerName, collectionMode);
	}

	CreateResponse createGroupAt(String serverUrl, String setupKey, String playerName,
		String collectionMode) throws IOException
	{
		return call("POST", url(serverUrl, "v1", "groups"),
			new MembershipRequest(playerName, collectionMode), null,
			CreateResponse.class, setupKey);
	}

	JoinResponse joinGroup(String groupId, String inviteCode, String playerName,
		String collectionMode) throws IOException
	{
		return joinGroupAt(configuredBaseUrl(), groupId, inviteCode, playerName, collectionMode);
	}

	JoinResponse joinGroupAt(String serverUrl, String groupId, String inviteCode,
		String playerName, String collectionMode) throws IOException
	{
		return call("POST", url(serverUrl, "v1", "join"),
			new JoinRequest(groupId, inviteCode, playerName, collectionMode), null,
			JoinResponse.class);
	}

	GroupResponse getGroup(HostedProfile profile) throws IOException
	{
		return call("GET", url(profile, "v1", "groups", profile.groupId), null, profile, GroupResponse.class);
	}

	void approveMember(HostedProfile profile, String memberId) throws IOException
	{
		call("POST", url(profile, "v1", "groups", profile.groupId, "members", memberId),
			new EmptyRequest(), profile, EmptyResponse.class);
	}

	void revokeMember(HostedProfile profile, String memberId) throws IOException
	{
		call("DELETE", url(profile, "v1", "groups", profile.groupId, "members", memberId),
			new EmptyRequest(), profile, EmptyResponse.class);
	}

	InviteResponse rotateInvite(HostedProfile profile) throws IOException
	{
		return call("POST", url(profile, "v1", "groups", profile.groupId, "invite"),
			new EmptyRequest(), profile, InviteResponse.class);
	}

	void uploadMemberCollection(HostedProfile profile, String snapshotId,
		List<CardInstanceUpload> instances, boolean complete, String collectionMode) throws IOException
	{
		call("POST", url(profile, "v1", "groups", profile.groupId, "member-collection"),
			new MemberCollectionRequest(snapshotId, complete, collectionMode, instances),
			profile, EmptyResponse.class);
	}

	void uploadPack(HostedProfile profile, PackUpload pack) throws IOException
	{
		call("POST", url(profile, "v1", "groups", profile.groupId, "packs"), pack, profile, EmptyResponse.class);
	}

	SyncResponse sync(HostedProfile profile, long cursor, long topTrumpsCursor,
		long collectionVersion) throws IOException
	{
		HttpUrl target = url(profile, "v1", "groups", profile.groupId, "sync").newBuilder()
			.addQueryParameter("after", Long.toString(Math.max(0L, cursor)))
			.addQueryParameter("topTrumpsAfter", Long.toString(Math.max(0L, topTrumpsCursor)))
			.addQueryParameter("collectionVersion", Long.toString(Math.max(0L, collectionVersion)))
			.addQueryParameter("limit", "100")
			.build();
		return call("GET", target, null, profile, SyncResponse.class);
	}

	TopTrumpsChallengeResponse createTopTrumpsChallenge(HostedProfile profile,
		String targetMemberId) throws IOException
	{
		return call("POST", url(profile, "v1", "groups", profile.groupId,
			"top-trumps", "challenges"), new TopTrumpsChallengeRequest(targetMemberId),
			profile, TopTrumpsChallengeResponse.class);
	}

	void respondTopTrumpsChallenge(HostedProfile profile, String challengeId,
		boolean accepted) throws IOException
	{
		call("POST", url(profile, "v1", "groups", profile.groupId,
			"top-trumps", "challenges", challengeId, "response"),
			new TopTrumpsResponseRequest(accepted), profile, EmptyResponse.class);
	}

	MemberCollectionsResponse getMemberCollections(HostedProfile profile) throws IOException
	{
		return call("GET", url(profile, "v1", "groups", profile.groupId, "member-collections"),
			null, profile, MemberCollectionsResponse.class);
	}

	MemberCollectionResponse getMemberCollection(HostedProfile profile, String memberId, int offset) throws IOException
	{
		HttpUrl target = url(profile, "v1", "groups", profile.groupId, "members", memberId, "collection").newBuilder()
			.addQueryParameter("offset", Integer.toString(Math.max(0, offset)))
			.addQueryParameter("limit", "200")
			.build();
		return call("GET", target, null, profile, MemberCollectionResponse.class);
	}

	String configuredBaseUrl() throws IOException
	{
		return resolveBaseUrl(null).toString();
	}

	private HttpUrl url(HostedProfile profile, String... segments) throws IOException
	{
		HttpUrl.Builder builder = resolveBaseUrl(profile).newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	private HttpUrl url(String serverUrl, String... segments) throws IOException
	{
		HttpUrl base;
		try
		{
			base = parseBaseUrl(serverUrl);
		}
		catch (IllegalArgumentException ex)
		{
			throw new IOException(ex.getMessage(), ex);
		}
		HttpUrl.Builder builder = base.newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	private HttpUrl resolveBaseUrl(HostedProfile profile) throws IOException
	{
		if (fixedBaseUrl != null)
		{
			return fixedBaseUrl;
		}
		String configured = profile != null && profile.serverUrl != null && !profile.serverUrl.trim().isEmpty()
			? profile.serverUrl : config.hostedServerUrl();
		try
		{
			return parseBaseUrl(configured);
		}
		catch (IllegalArgumentException ex)
		{
			throw new IOException(ex.getMessage(), ex);
		}
	}

	private static HttpUrl parseBaseUrl(String value)
	{
		HttpUrl parsed = value == null ? null : HttpUrl.parse(value.trim());
		if (parsed == null || parsed.host().isEmpty() || !parsed.username().isEmpty()
			|| !parsed.password().isEmpty() || parsed.querySize() > 0 || parsed.fragment() != null
			|| !"/".equals(parsed.encodedPath()))
		{
			throw new IllegalArgumentException("Server URL must be a root such as https://example.workers.dev");
		}
		boolean local = "localhost".equals(parsed.host()) || "127.0.0.1".equals(parsed.host())
			|| "::1".equals(parsed.host());
		if (!"https".equals(parsed.scheme()) && !(local && "http".equals(parsed.scheme())))
		{
			throw new IllegalArgumentException("Server URL must use HTTPS (HTTP is allowed only for localhost)");
		}
		return parsed;
	}

	private <T> T call(String method, HttpUrl url, Object body, HostedProfile profile,
		Class<T> responseType) throws IOException
	{
		return call(method, url, body, profile, responseType, null);
	}

	private <T> T call(String method, HttpUrl url, Object body, HostedProfile profile,
		Class<T> responseType, String setupKey) throws IOException
	{
		Request.Builder request = new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.header("User-Agent", "Group-TCG/1.0.0");
		if (setupKey != null && !setupKey.isEmpty())
		{
			request.header("X-Groupman-Setup-Key", setupKey);
		}
		if (profile != null)
		{
			request.header("Authorization", "Bearer " + profile.token);
		}
		if ("GET".equals(method))
		{
			request.get();
		}
		else
		{
			request.method(method, RequestBody.create(JSON, gson.toJson(body)));
		}

		try (Response response = http.newCall(request.build()).execute())
		{
			ResponseBody responseBody = response.body();
			String json = responseBody == null ? "" : responseBody.string();
			if (!response.isSuccessful())
			{
				ErrorEnvelope error = parseError(json);
				throw new HostedApiException(response.code(), error.code,
					error.message == null ? "The hosted service returned HTTP " + response.code() : error.message);
			}
			if (responseType == EmptyResponse.class || json.isEmpty())
			{
				return responseType.cast(new EmptyResponse());
			}
			T parsed = gson.fromJson(json, responseType);
			if (parsed == null)
			{
				throw new IOException("The hosted service returned an empty response");
			}
			return parsed;
		}
	}

	private ErrorEnvelope parseError(String json)
	{
		try
		{
			ErrorResponse response = gson.fromJson(json, ErrorResponse.class);
			return response != null && response.error != null ? response.error : new ErrorEnvelope();
		}
		catch (RuntimeException ex)
		{
			return new ErrorEnvelope();
		}
	}

	static final class CreateResponse
	{
		GroupRef group;
		MemberRef member;
		Invite invite;
	}

	static final class JoinResponse
	{
		MemberRef member;
	}

	static final class GroupResponse
	{
		GroupRef group;
		MemberRef currentMember;
		List<MemberRef> members = Collections.emptyList();
	}

	static final class InviteResponse
	{
		Invite invite;
	}

	static final class MemberCollectionsResponse
	{
		List<MemberSummary> members = Collections.emptyList();
	}

	static final class MemberCollectionResponse
	{
		MemberRef member;
		int nextOffset;
		boolean hasMore;
		List<CardInstanceResult> instances = Collections.emptyList();
	}

	static final class SyncResponse
	{
		long nextCursor;
		boolean hasMore;
		List<PackEvent> events = Collections.emptyList();
		long topTrumpsNextCursor;
		List<TopTrumpsEvent> topTrumpsEvents = Collections.emptyList();
		CollectionResult collection;
	}

	static final class GroupRef
	{
		String id;
		long collectionVersion;
	}

	static final class MemberRef
	{
		String id;
		String groupId;
		String label;
		String playerName;
		String collectionMode;
		String role;
		String status;
		String token;
		boolean revoked;
	}

	static final class TopTrumpsChallengeResponse
	{
		String challengeId;
		long expiresAt;
	}

	static final class TopTrumpsEvent
	{
		long sequence;
		String challengeId;
		String type;
		long createdAt;
		long expiresAt;
		MemberRef challenger;
		MemberRef challenged;
		String challengerCard;
		String challengedCard;
	}

	static final class Invite
	{
		String code;
		long expiresAt;
	}

	static final class MemberSummary
	{
		String id;
		String label;
		String playerName;
		String collectionMode;
		int cards;
		int copies;
		int foils;
	}

	static final class CardInstanceResult
	{
		String sourceInstanceId;
		String cardName;
		boolean foil;
		long pulledAt;
		String acquisitionKind;
	}

	static final class PackEvent
