package com.groupmantcg;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

/** Read-only view of the active RuneScape profile's OSRS TCG collection. */
@Slf4j
@Singleton
class LocalCollection
{
	private static final long CACHE_MILLIS = 3_000L;
	private static final String OSRS_TCG_STATE_PREFIX = "RLTCG_v2:";
	private static final String DEFAULT_PROFILE_DIRECTORY = "default";
	private final ConfigManager configManager;
	private final Gson gson;
	private final OsrsTcgInteropService osrsTcgInterop;

	private Set<String> cards = Collections.emptySet();
	private Snapshot snapshot = Snapshot.empty();
	private long refreshedAt;
	private boolean available;

	@Inject
	LocalCollection(ConfigManager configManager, Gson gson, OsrsTcgInteropService osrsTcgInterop)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.osrsTcgInterop = osrsTcgInterop;
	}

	synchronized Set<String> getCards()
	{
		if (System.currentTimeMillis() - refreshedAt >= CACHE_MILLIS)
		{
			refresh();
		}
		return cards;
	}

	synchronized boolean isAvailable()
	{
		getCards();
		return available;
	}

	synchronized Snapshot snapshot()
	{
		getCards();
		return snapshot;
	}

	synchronized CardSummary summary(String normalizedCardName)
	{
		Snapshot current = snapshot();
		int normalCopies = 0;
		int foilCopies = 0;
		int debugCopies = 0;
		long firstPulledAt = 0L;
		long lastPulledAt = 0L;
		Set<String> pulledBy = new LinkedHashSet<>();
		for (CardInstance instance : current.instances())
		{
			if (!instance.normalizedName().equals(normalizedCardName))
			{
				continue;
			}
			if (instance.foil())
			{
				foilCopies++;
			}
			else
			{
				normalCopies++;
			}
			if (!instance.pulledBy().isEmpty())
			{
				if (isDebugPull(instance.pulledBy()))
				{
					debugCopies++;
				}
				pulledBy.add(formatPulledBy(instance.pulledBy()));
			}
			if (instance.pulledAt() > 0L)
			{
				firstPulledAt = firstPulledAt == 0L
					? instance.pulledAt() : Math.min(firstPulledAt, instance.pulledAt());
				lastPulledAt = Math.max(lastPulledAt, instance.pulledAt());
			}
		}
		int copies = normalCopies + foilCopies;
		return copies == 0 ? null : new CardSummary(normalCopies, foilCopies, debugCopies, firstPulledAt,
			lastPulledAt, pulledBy);
	}

	synchronized void invalidate()
	{
		refreshedAt = 0L;
	}

	private void refresh()
	{
		refreshedAt = System.currentTimeMillis();
		try
		{
			OsrsTcgInteropService.Snapshot api = osrsTcgInterop.snapshot();
			String stored = freshestStoredState();
			String json = StoredTcgStateDecoder.decode(stored);
			StoredTcgState state = json.isEmpty() ? null : gson.fromJson(json, StoredTcgState.class);
			if (!api.available() && (state == null || !state.hasCollectionData()))
			{
				clear();
				return;
			}

			Set<String> names = api.available()
				? new HashSet<>(api.ownedNames().keySet()) : new HashSet<>();
			List<CardInstance> instances = new ArrayList<>();
			if (state != null && state.hasCollectionData())
			{
				for (StoredTcgState.CardInstance card : state.expandedCardInstances())
				{
					if (card != null && card.cardName != null && !card.cardName.trim().isEmpty())
					{
						String displayName = card.cardName.trim();
						String normalizedName = displayName.toLowerCase(Locale.ROOT);
						if (!api.available())
						{
							names.add(normalizedName);
						}
						if (card.id != null && !card.id.trim().isEmpty())
						{
							if (api.available() && (!names.contains(normalizedName)
								|| (api.foilDataAvailable() && card.foil
								&& !api.foilNames().contains(normalizedName))))
							{
								continue;
							}
							instances.add(new CardInstance(card.id.trim(), displayName, normalizedName,
								card.foil, card.pulledBy == null ? "" : card.pulledBy.trim(), card.pulledAt));
						}
					}
				}
			}
			if (api.available())
			{
				addMissingApiInstances(instances, api);
			}
			cards = Collections.unmodifiableSet(names);
			snapshot = new Snapshot(state == null ? 0L : state.openedPacks, instances, true);
			available = true;
		}
		catch (Exception ex)
		{
			clear();
			log.debug("Unable to read OSRS TCG collection", ex);
		}
	}

	private static void addMissingApiInstances(List<CardInstance> instances,
		OsrsTcgInteropService.Snapshot api)
	{
		for (java.util.Map.Entry<String, String> owned : api.ownedNames().entrySet())
		{
			String normalized = owned.getKey();
			boolean hasNormal = false;
			boolean hasFoil = false;
			for (CardInstance instance : instances)
			{
				if (normalized.equals(instance.normalizedName()))
				{
					hasFoil |= instance.foil();
					hasNormal |= !instance.foil();
				}
			}
			boolean apiHasFoil = api.foilDataAvailable() && api.foilNames().contains(normalized);
			if (!hasNormal && !hasFoil)
			{
				addApiInstance(instances, owned.getValue(), normalized, apiHasFoil);
				hasFoil = apiHasFoil;
				hasNormal = !apiHasFoil;
			}
			if (apiHasFoil && !hasFoil)
			{
				addApiInstance(instances, owned.getValue(), normalized, true);
			}
			if (api.foilDataAvailable() && !apiHasFoil && !hasNormal)
			{
				addApiInstance(instances, owned.getValue(), normalized, false);
			}
		}
	}

	private static void addApiInstance(List<CardInstance> instances, String displayName,
		String normalizedName, boolean foil)
	{
		String identity = "osrstcg-v1\0" + normalizedName + "\0" + foil;
		String id = "api-" + UUID.nameUUIDFromBytes(identity.getBytes(StandardCharsets.UTF_8));
		instances.add(new CardInstance(id, displayName, normalizedName, foil, "OSRS TCG", 0L));
	}

	/**
	 * OSRS TCG 0.18 writes collection changes to its atomic per-profile master save immediately,
	 * while the RuneLite profile configuration is now only a checkpoint. Prefer the master so
	 * collection sharing and pack detection see pulls made during the current session.
	 */
	private String freshestStoredState()
	{
		String profileKey = configManager.getRSProfileKey();
		String profileDirectory = profileKey == null || profileKey.isEmpty()
			? DEFAULT_PROFILE_DIRECTORY : sha256(profileKey);
		if (profileDirectory != null)
		{
			Path master = Path.of(RuneLite.RUNELITE_DIR.getAbsolutePath(), "OSRS-TCG", "backups",
				profileDirectory, "tcg.save");
			try
			{
				if (Files.isRegularFile(master))
				{
					String stored = Files.readString(master, StandardCharsets.UTF_8).trim();
					if (stored.startsWith(OSRS_TCG_STATE_PREFIX))
					{
						return stored;
					}
				}
			}
			catch (IOException ex)
			{
				log.debug("Unable to read the current OSRS TCG master save", ex);
			}
		}
		return configManager.getRSProfileConfiguration("osrstcg", "state");
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte current : digest)
			{
				hex.append(String.format(Locale.ROOT, "%02x", current & 0xff));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			log.debug("SHA-256 is unavailable; falling back to the OSRS TCG profile checkpoint", ex);
			return null;
		}
	}

	private void clear()
	{
		cards = Collections.emptySet();
		snapshot = Snapshot.empty();
		available = false;
	}

	private static String formatPulledBy(String pulledBy)
	{
		String clean = pulledBy.trim();
		return isDebugPull(clean) ? "Debug_" + clean.substring("DEBUG_".length()) : clean;
	}

	private static boolean isDebugPull(String pulledBy)
	{
		return pulledBy.regionMatches(true, 0, "DEBUG_", 0, "DEBUG_".length());
	}

	static final class Snapshot
	{
		private final long openedPacks;
		private final List<CardInstance> instances;
		private final boolean available;

		Snapshot(long openedPacks, List<CardInstance> instances, boolean available)
		{
			this.openedPacks = Math.max(0L, openedPacks);
			this.instances = Collections.unmodifiableList(new ArrayList<>(instances));
			this.available = available;
		}

		static Snapshot empty()
		{
			return new Snapshot(0L, Collections.emptyList(), false);
		}

		long openedPacks()
		{
			return openedPacks;
		}

		List<CardInstance> instances()
		{
			return instances;
		}

		boolean available()
		{
			return available;
		}
	}

	static final class CardInstance
	{
		private final String id;
		private final String displayName;
		private final String normalizedName;
		private final boolean foil;
		private final String pulledBy;
		private final long pulledAt;

		CardInstance(String id, String displayName, String normalizedName, boolean foil,
			String pulledBy, long pulledAt)
		{
			this.id = id;
			this.displayName = displayName;
			this.normalizedName = normalizedName;
			this.foil = foil;
			this.pulledBy = pulledBy;
			this.pulledAt = pulledAt;
		}

		String id() { return id; }
		String displayName() { return displayName; }
		String normalizedName() { return normalizedName; }
		boolean foil() { return foil; }
		String pulledBy() { return pulledBy; }
		long pulledAt() { return pulledAt; }
	}

	static final class CardSummary
	{
		private final int normalCopies;
		private final int foilCopies;
		private final int debugCopies;
		private final long firstPulledAt;
		private final long lastPulledAt;
		private final Set<String> pulledBy;

		private CardSummary(int normalCopies, int foilCopies, int debugCopies, long firstPulledAt,
			long lastPulledAt, Set<String> pulledBy)
		{
			this.normalCopies = normalCopies;
			this.foilCopies = foilCopies;
			this.debugCopies = debugCopies;
			this.firstPulledAt = firstPulledAt;
			this.lastPulledAt = lastPulledAt;
			this.pulledBy = Collections.unmodifiableSet(new LinkedHashSet<>(pulledBy));
		}

		int normalCopies() { return normalCopies; }
		int foilCopies() { return foilCopies; }
		int debugCopies() { return debugCopies; }
		int copies() { return normalCopies + foilCopies; }
		long firstPulledAt() { return firstPulledAt; }
		long lastPulledAt() { return lastPulledAt; }
		Set<String> pulledBy() { return pulledBy; }
	}
}

