final class OsrsTcgCardRenderer
{
	public static final int DEFAULT_CARD_WIDTH = 180;
	public static final int DEFAULT_CARD_HEIGHT = 260;
	/** Border thickness at {@link #DEFAULT_CARD_WIDTH}×{@link #DEFAULT_CARD_HEIGHT}; scaled per draw via {@link #frameThicknessFor}. */
	private static final int FRAME_THICKNESS = 6;
	private static final Color FOIL_FRAME_GOLD = new Color(0xD4AF37);
	/** Light gold fill for the moving foil sheen; opacity comes from {@link AlphaComposite}. */
	private static final Color FOIL_SHEEN_GOLD = new Color(255, 236, 190);
	private static final Color FOIL_SPARKLE_CORE = new Color(255, 215, 105);
	/** Peak opacity when a twinkle is at full size ({@code scaleEnv == 1}). */
	private static final float FOIL_TWINKLE_PEAK_ALPHA = 0.75f;
	/** Inward scoop of foil twinkle star edges; lower = sharper tips (control closer to center). */
	private static final float FOIL_TWINKLE_CONCAVE_K = 0.11f;
	/** Active sheen sweep duration (ms); half of prior 1150 ms = double sweep speed. */
	private static final int FOIL_SHEEN_SWEEP_MS = 575;
	/** Foil sparkle animation target frame rate. */
	public static final int FOIL_SPARKLE_FPS = 60;
	/** Milliseconds between foil sparkle repaints ({@value #FOIL_SPARKLE_FPS} FPS). */
	public static final int FOIL_SPARKLE_FRAME_MS = 1000 / FOIL_SPARKLE_FPS;
	/** Idle time after each sweep before the next (ms). */
	private static final int FOIL_SHEEN_COOLDOWN_MS = 5000;
	private static final int FOIL_SHEEN_CYCLE_MS = FOIL_SHEEN_SWEEP_MS + FOIL_SHEEN_COOLDOWN_MS;
	private static final Color CARD_BG = new Color(0x2A2A2A);
	private static final Color PANEL_DARK = new Color(0x222222);
	private static final Color PANEL_MID = new Color(0x2F2F2F);
	private static final BufferedImage CARD_BACK_IMAGE = ImageUtil.loadImageResource(OsrsTcgCardRenderer.class,
		"/osrs-tcg/Cardback.png");
	private static final BufferedImage LOCK_BADGE_IMAGE = ImageUtil.loadImageResource(OsrsTcgCardRenderer.class,
		"/osrs-tcg/lock.png");
	private static final Map<Long, Path2D.Float> FOIL_TWINKLE_PATH_CACHE = new ConcurrentHashMap<>();

	private OsrsTcgCardRenderer()
	{
	}

	public static void drawCardBack(Graphics2D g, Rectangle bounds, boolean foil, Color rarityColor)
	{
		if (g == null || bounds == null)
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			enableQuality(g2);
			if (CARD_BACK_IMAGE != null)
			{
				drawCoverCentered(g2, CARD_BACK_IMAGE, bounds);
				return;
			}

			int ft = frameThicknessFor(bounds);
			int outerArc = outerFrameArc(bounds);
			drawFrame(g2, bounds, foil, rarityColor, ft, outerArc);
			Rectangle inner = inset(bounds, ft + 1);
			int innerArc = Math.max(2, outerArc - 2);
			g2.setColor(CARD_BG);
			g2.fillRoundRect(inner.x, inner.y, inner.width, inner.height, innerArc, innerArc);
			drawCenteredText(g2, inner, "OSRS TCG", FontManager.getRunescapeBoldFont(), Color.WHITE);
		}
		finally
		{
			g2.dispose();
		}
	}

	public static void drawCardFace(Graphics2D g, Rectangle bounds, CardVisualCatalog.CardVisual card,
		boolean foil, Color rarityColor)
	{
		drawCardFace(g, bounds, card, foil, rarityColor, null, 0);
	}

	public static void drawCardFace(Graphics2D g, Rectangle bounds, CardVisualCatalog.CardVisual card,
		boolean foil, Color rarityColor, BufferedImage linkedImage)
	{
		drawCardFace(g, bounds, card, foil, rarityColor, linkedImage, 0);
	}

	public static void drawCardFace(Graphics2D g, Rectangle bounds, CardVisualCatalog.CardVisual card,
		boolean foil, Color rarityColor, BufferedImage linkedImage, long basePullDenominator)
	{
		drawCardFace(g, bounds, card, foil, rarityColor, linkedImage, basePullDenominator, foil);
	}

	/**
	 * @param useFoilAdjustedScoreForLabel when true, the stats line uses the
	 *        same foil-adjusted score formula as OSRS TCG. Frame foil is still {@code foil}.
	 */
	public static void drawCardFace(Graphics2D g, Rectangle bounds, CardVisualCatalog.CardVisual card,
		boolean foil, Color rarityColor, BufferedImage linkedImage, long basePullDenominator,
		boolean useFoilAdjustedScoreForLabel)
	{
		if (g == null || bounds == null)
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			enableQuality(g2);
			int ft = frameThicknessFor(bounds);
			int outerArc = outerFrameArc(bounds);
			drawFrame(g2, bounds, foil, rarityColor, ft, outerArc);

			Rectangle inner = inset(bounds, ft + 1);
			int innerArc = Math.max(2, outerArc - 2);
			g2.setColor(CARD_BG);
			g2.fillRoundRect(inner.x, inner.y, inner.width, inner.height, innerArc, innerArc);

			int y = inner.y;
			int titleH = pct(inner.height, 0.10d);
			int imageH = pct(inner.height, 0.40d);
			int tierH = pct(inner.height, 0.10d);
			int examineH = pct(inner.height, 0.30d);
			int statsH = inner.height - titleH - imageH - tierH - examineH;

			Rectangle titleR = new Rectangle(inner.x, y, inner.width, titleH);
			y += titleH;
			Rectangle imageR = new Rectangle(inner.x, y, inner.width, imageH);
			y += imageH;
			Rectangle tierR = new Rectangle(inner.x, y, inner.width, tierH);
			y += tierH;
			Rectangle examineR = new Rectangle(inner.x, y, inner.width, examineH);
			y += examineH;
			Rectangle statsR = new Rectangle(inner.x, y, inner.width, statsH);

			Color themedDark = blend(PANEL_DARK, safeColor(rarityColor), 0.32f);
			Color themedMid = blend(PANEL_MID, safeColor(rarityColor), 0.20f);
			fillSection(g2, titleR, themedDark);
			fillSection(g2, imageR, themedMid);
			fillSection(g2, tierR, themedDark);
			fillSection(g2, examineR, themedMid);
			fillSection(g2, statsR, themedDark);

			drawCenteredText(g2, titleR, valueOrFallback(card == null ? null : card.displayName(), "Unknown Card"),
				FontManager.getRunescapeSmallFont(), safeColor(rarityColor).brighter(), 2);

			drawImageSection(g2, imageR, card, linkedImage);

			String rarity = tierLabelForRarityColor(safeColor(rarityColor));
			drawCenteredText(g2, tierR, rarity, FontManager.getRunescapeSmallFont(), safeColor(rarityColor).brighter());

			Font exFont = FontManager.getRunescapeSmallFont();
			FontMetrics fmExamine = g2.getFontMetrics(exFont);
			int examineLineH = Math.max(1, fmExamine.getHeight());
			// Never allow more lines than fit in the examine band (was Math.max(6, …), which overflowed small cards).
			int examineVerticalPad = 6;
			int maxExamineLines = Math.max(1, (examineR.height - examineVerticalPad) / examineLineH);

			String examine = valueOrFallback(card == null ? null : card.examine(), "No examine text.");
			drawWrappedCentered(g2, examineR, examine, exFont, ColorScheme.LIGHT_GRAY_COLOR, maxExamineLines, 8);

			String stats = "Score: " + formatScore(card, useFoilAdjustedScoreForLabel);
			drawCenteredText(g2, statsR, stats, FontManager.getRunescapeSmallFont(), Color.WHITE);

			if (foil)
			{
				drawFoilSheen(g2, bounds, outerArc);
				drawFoilSparkles(g2, bounds, outerArc, ft, card);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/** Deterministic fraction in {@code [0, 1)} for foil sparkle layout (per star index + salt). */
	private static double sparkleU01(long seed, int i, int salt)
	{
		long z = seed + (long) i * 0x9E3779B97L + (long) salt * 0xC2B2AE3D27A4EB4FL;
		z ^= z >>> 33;
		z *= 0xff51afd7ed558ccdL;
		z ^= z >>> 33;
		z *= 0xc4ceb9fe1a85ec53L;
		z ^= z >>> 33;
		long m = (z >>> 12) & ((1L << 52) - 1);
		return m * 0x1.0p-52;
	}

	/** True during the short foil sheen sweep; idle most of each {@link #FOIL_SHEEN_CYCLE_MS} cycle. */
	public static boolean isFoilSheenAnimating()
	{
		return System.currentTimeMillis() % FOIL_SHEEN_CYCLE_MS < FOIL_SHEEN_SWEEP_MS;
	}

	/**
	 * Four-point star with concave edges between points (taller than wide), centered at the origin.
	 * @param halfW east–west extent from center to tip
	 * @param halfH north–south extent from center to tip (typically &gt; halfW)
	 */
	private static Path2D.Float foilTwinklePath(float halfW, float halfH)
	{
		long key = ((long) Float.floatToIntBits(halfW) << 32) ^ Float.floatToIntBits(halfH);
		return FOIL_TWINKLE_PATH_CACHE.computeIfAbsent(key, k ->
		{
			float concave = FOIL_TWINKLE_CONCAVE_K;
			Path2D.Float p = new Path2D.Float();
			p.moveTo(0f, -halfH);
			p.quadTo(concave * halfW, -concave * halfH, halfW, 0f);
			p.quadTo(concave * halfW, concave * halfH, 0f, halfH);
			p.quadTo(-concave * halfW, concave * halfH, -halfW, 0f);
			p.quadTo(-concave * halfW, -concave * halfH, 0f, -halfH);
			p.closePath();
			return p;
		});
	}

	/**
	 * Diagonal semi-transparent gold band (45°) over the full card (including frame). One fast sweep every
	 * {@link #FOIL_SHEEN_SWEEP_MS}, then {@link #FOIL_SHEEN_COOLDOWN_MS} idle.
	 */
	private static void drawFoilSheen(Graphics2D g2, Rectangle clipBounds, int clipArc)
	{
		if (g2 == null || clipBounds == null || clipBounds.width < 6 || clipBounds.height < 6)
		{
			return;
		}

		long t = System.currentTimeMillis();
		long cyclePos = t % FOIL_SHEEN_CYCLE_MS;
		if (cyclePos >= FOIL_SHEEN_SWEEP_MS)
		{
			return;
		}
		double u = cyclePos / (double) FOIL_SHEEN_SWEEP_MS;

		int arc = Math.max(2, clipArc);
		java.awt.Shape clipBefore = g2.getClip();
		java.awt.Composite compositeBefore = g2.getComposite();
		java.awt.geom.AffineTransform transformBefore = g2.getTransform();
		try
		{
			RoundRectangle2D clipShape = new RoundRectangle2D.Float(
				clipBounds.x, clipBounds.y, clipBounds.width, clipBounds.height, arc, arc);
			g2.clip(clipShape);

			double cx = clipBounds.getCenterX();
			double cy = clipBounds.getCenterY();
			double diag = Math.hypot(clipBounds.width, clipBounds.height);
			int sheenW = Math.max(10, (int) Math.round(Math.min(clipBounds.width, clipBounds.height) * 0.15d));
			int span = (int) Math.ceil(diag) + sheenW + 8;
			double th = Math.PI / 4.0d;
			// Screen-space half-height of the rotated band (axis-aligned bounds).
			double halfBandH = 0.5d * (Math.abs(sheenW * Math.sin(th)) + Math.abs(span * Math.cos(th)));
			double extra = Math.max(4.0d, sheenW);
			// u=0: band fully above the card; u=1: fully below — then loop.
			double travelStart = -clipBounds.height / 2.0d - halfBandH - extra;
			double travelEnd = clipBounds.height / 2.0d + halfBandH + extra;
			double travel = travelStart + u * (travelEnd - travelStart);

			g2.translate(cx, cy + travel);
			g2.rotate(th);

			g2.setComposite(AlphaComposite.SrcOver.derive(0.40f));
			g2.setColor(FOIL_SHEEN_GOLD);
			g2.fillRect(-sheenW / 2, -span / 2, sheenW, span);
		}
		finally
		{
			g2.setTransform(transformBefore);
			g2.setComposite(compositeBefore);
			g2.setClip(clipBefore);
		}
	}

	/** Fewer sparkles; each twinkle grows from 0 to full size then shrinks to 0; position changes each cycle. */
	private static void drawFoilSparkles(Graphics2D g2, Rectangle clipBounds, int clipArc,
		int frameThickness, CardVisualCatalog.CardVisual card)
	{
		if (g2 == null || clipBounds == null || clipBounds.width < 8 || clipBounds.height < 8)
		{
			return;
		}

		int arc = Math.max(2, clipArc);
		String key = valueOrFallback(card == null ? null : card.displayName(), "Unknown");
		long seed = (long) key.hashCode() ^ ((long) key.length() << 32) ^ 0xC0FFEE8BADF00DL;

		java.awt.Shape clipBefore = g2.getClip();
		java.awt.Composite compositeBefore = g2.getComposite();
		java.awt.Stroke strokeBefore = g2.getStroke();
		try
		{
			float scale = Math.max(0.35f, Math.min(clipBounds.width, clipBounds.height) / 260.0f);
			float twinkleArmPx = Math.max(5f, (float) (3.55d * scale * 1.62d * 2.0d));

			// Inside the frame, with extra pad so full-size star tips stay off the border.
			int borderInset = Math.max(1, frameThickness) + 1;
			int tipPad = Math.max(2, (int) Math.ceil(twinkleArmPx * 1.12f));
			Rectangle sparkleArea = inset(clipBounds, borderInset);
			int sparkleArc = Math.max(2, arc - 2);
			Rectangle posArea = inset(sparkleArea, tipPad);
			if (posArea.width < 6 || posArea.height < 6)
			{
				posArea = sparkleArea;
			}

			RoundRectangle2D clipShape = new RoundRectangle2D.Float(
				sparkleArea.x, sparkleArea.y, sparkleArea.width, sparkleArea.height, sparkleArc, sparkleArc);
			g2.clip(clipShape);

			int count = 6 + (int) (sparkleU01(seed, 0, 77) * 6);
			int margin = Math.max(1, Math.round(2 * scale));
			int posW = Math.max(1, posArea.width - margin * 2);
			int posH = Math.max(1, posArea.height - margin * 2);
			long now = System.currentTimeMillis();

			for (int i = 0; i < count; i++)
			{
				int period = 1100 + (int) (sparkleU01(seed, i, 6) * 2400);
				int phase = (int) (sparkleU01(seed, i, 7) * period);
				long tWave = now + phase;
				long cycleIndex = tWave / period;
				long posSeed = seed ^ (cycleIndex * 0x9E3779B97L) ^ ((long) i << 21);

				int px = posArea.x + margin + (int) (sparkleU01(posSeed, i, 1) * posW);
				int py = posArea.y + margin + (int) (sparkleU01(posSeed, i, 2) * posH);

				long uMod = ((tWave % period) + period) % period;
				double u = uMod / (double) period;
				// One smooth pulse per period: 0 → 1 → 0 (size and fade).
				double scaleEnv = Math.sin(Math.PI * u);
				if (scaleEnv < 0.012d)
				{
					continue;
				}

				float halfW = twinkleArmPx * 0.86f;
				float halfH = twinkleArmPx * 1.12f;
				Path2D.Float twShape = foilTwinklePath(halfW, halfH);
				AffineTransform at = new AffineTransform();
				at.translate(px, py);
				at.scale(scaleEnv, scaleEnv);
				java.awt.Shape drawn = at.createTransformedShape(twShape);

				g2.setColor(FOIL_SPARKLE_CORE);
				g2.setComposite(AlphaComposite.SrcOver.derive(FOIL_TWINKLE_PEAK_ALPHA * (float) scaleEnv));
				g2.fill(drawn);
			}
		}
		finally
		{
			g2.setStroke(strokeBefore);
			g2.setComposite(compositeBefore);
			g2.setClip(clipBefore);
		}
	}

	private static int frameThicknessFor(Rectangle bounds)
	{
		if (bounds == null || bounds.width < 4 || bounds.height < 4)
		{
			return 2;
		}
		double scale = Math.min(
			bounds.width / (double) DEFAULT_CARD_WIDTH,
			bounds.height / (double) DEFAULT_CARD_HEIGHT);
		int t = (int) Math.round(FRAME_THICKNESS * scale);
		int maxBySize = Math.max(2, Math.min(bounds.width, bounds.height) / 4);
		return Math.max(2, Math.min(t, maxBySize));
	}

	private static int outerFrameArc(Rectangle bounds)
	{
		if (bounds == null)
		{
			return 12;
		}
		int a = (int) Math.round(12.0d * bounds.width / (double) DEFAULT_CARD_WIDTH);
		int cap = Math.max(4, Math.min(bounds.width, bounds.height) / 2);
		return Math.max(3, Math.min(a, cap));
	}

	@SuppressWarnings("unused")
	private static void drawFrame(Graphics2D g2, Rectangle bounds, boolean foil, Color accent, int frameThickness, int outerArc)
	{
		g2.setColor(foil ? FOIL_FRAME_GOLD : Color.BLACK);
		g2.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, outerArc, outerArc);
		Color strokeColor = foil ? new Color(120, 90, 20, 200) : new Color(0, 0, 0, 180);
		g2.setColor(strokeColor);
		for (int i = 0; i < frameThickness; i++)
		{
			g2.drawRoundRect(bounds.x + i, bounds.y + i, bounds.width - (i * 2) - 1, bounds.height - (i * 2) - 1, outerArc, outerArc);
		}

		if (foil)
		{
			int innerArc = Math.max(2, outerArc - 2);
			g2.setColor(new Color(255, 255, 255, 28));
			g2.drawRoundRect(bounds.x + frameThickness, bounds.y + frameThickness,
				bounds.width - (frameThickness * 2) - 1, bounds.height - (frameThickness * 2) - 1, innerArc, innerArc);
			return;
		}

		g2.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, outerArc, outerArc);
	}

	private static void fillSection(Graphics2D g2, Rectangle rect, Color base)
	{
		g2.setPaint(new GradientPaint(rect.x, rect.y, base.brighter(), rect.x, rect.y + rect.height, base));
		g2.fillRoundRect(rect.x + 1, rect.y + 1, Math.max(1, rect.width - 2), Math.max(1, rect.height - 2), 6, 6);
	}

	private static void drawCenteredText(Graphics2D g2, Rectangle rect, String text, Font font, Color color)
	{
		drawCenteredText(g2, rect, text, font, color, 0);
	}

	private static void drawCenteredText(Graphics2D g2, Rectangle rect, String text, Font font, Color color, int horizontalPadding)
	{
		g2.setFont(font == null ? FontManager.getRunescapeSmallFont() : font);
		g2.setColor(color == null ? Color.WHITE : color);
		FontMetrics fm = g2.getFontMetrics();
		int safePadding = Math.max(0, horizontalPadding);
		int maxWidth = Math.max(1, rect.width - (safePadding * 2));
		String value = ellipsizeToWidth(valueOrFallback(text, ""), fm, maxWidth);
		int x = rect.x + safePadding + Math.max(0, (maxWidth - fm.stringWidth(value)) / 2);
		int y = rect.y + ((rect.height - fm.getHeight()) / 2) + fm.getAscent();
		g2.drawString(value, x, y);
	}

	private static void drawWrappedCentered(Graphics2D g2, Rectangle rect, String text, Font font, Color color, int maxLines, int horizontalPadding)
	{
		g2.setFont(font == null ? FontManager.getRunescapeSmallFont() : font);
		g2.setColor(color == null ? Color.WHITE : color);
		FontMetrics fm = g2.getFontMetrics();
		String value = valueOrFallback(text, "");

		int safePadding = Math.max(0, horizontalPadding);
		int maxWidth = Math.max(20, rect.width - (safePadding * 2));
		int linesCap = Math.max(1, maxLines);
		String[] words = value.split("\\s+");
		java.util.List<String> lines = new java.util.ArrayList<>();
		StringBuilder current = new StringBuilder();

		for (String rawWord : words)
		{
			String word = rawWord == null ? "" : rawWord.trim();
			if (word.isEmpty())
			{
				continue;
			}

			String candidate = current.length() == 0 ? word : current + " " + word;
			if (fm.stringWidth(candidate) <= maxWidth)
			{
				current = new StringBuilder(candidate);
				continue;
			}

			if (current.length() > 0)
			{
				lines.add(current.toString());
			}
			current = new StringBuilder(word);
		}

		if (current.length() > 0)
		{
			lines.add(current.toString());
		}

		if (lines.isEmpty())
		{
			lines.add("");
		}

		if (lines.size() > linesCap)
		{
			java.util.List<String> kept = new java.util.ArrayList<>(lines.subList(0, linesCap - 1));
			StringBuilder tail = new StringBuilder();
			for (int i = linesCap - 1; i < lines.size(); i++)
			{
				if (tail.length() > 0)
				{
					tail.append(' ');
				}
				tail.append(lines.get(i));
			}
			kept.add(ellipsizeToWidth(tail.toString(), fm, maxWidth));
			lines = kept;
		}

		int lastIdx = lines.size() - 1;
		lines.set(lastIdx, ellipsizeToWidth(lines.get(lastIdx), fm, maxWidth));

		int lineHeight = fm.getHeight();
		int totalHeight = lineHeight * lines.size();
		int y = rect.y + (rect.height - totalHeight) / 2 + fm.getAscent();

		java.awt.Shape previousClip = g2.getClip();
		try
		{
			g2.clip(rect);
			for (String lineText : lines)
			{
				int x = rect.x + safePadding + Math.max(0, (maxWidth - fm.stringWidth(lineText)) / 2);
				g2.drawString(lineText, x, y);
				y += lineHeight;
			}
		}
		finally
		{
			g2.setClip(previousClip);
		}
	}

	private static void drawTwoLineCentered(Graphics2D g2, Rectangle rect, String top, String bottom, Font font, Color color)
	{
		g2.setFont(font == null ? FontManager.getRunescapeSmallFont() : font);
		g2.setColor(color == null ? Color.WHITE : color);
		FontMetrics fm = g2.getFontMetrics();
		int totalHeight = fm.getHeight() * 2;
		int startY = rect.y + (rect.height - totalHeight) / 2 + fm.getAscent();

		String t = valueOrFallback(top, "");
		String b = valueOrFallback(bottom, "");
		int topX = rect.x + (rect.width - fm.stringWidth(t)) / 2;
		int bottomX = rect.x + (rect.width - fm.stringWidth(b)) / 2;
		g2.drawString(t, topX, startY);
		g2.drawString(b, bottomX, startY + fm.getHeight());
	}

	private static void drawFitCentered(Graphics2D g2, BufferedImage image, Rectangle rect)
	{
		int sourceWidth = image.getWidth();
		int sourceHeight = image.getHeight();
		if (sourceWidth <= 0 || sourceHeight <= 0)
		{
			return;
		}
		double ratio = Math.min((double) rect.width / sourceWidth, (double) rect.height / sourceHeight);
		int w = Math.max(1, (int) Math.round(sourceWidth * ratio));
		int h = Math.max(1, (int) Math.round(sourceHeight * ratio));
		int x = rect.x + (rect.width - w) / 2;
		int y = rect.y + (rect.height - h) / 2;
		java.awt.Shape previousClip = g2.getClip();
		try
		{
			g2.setClip(rect);
			g2.drawImage(image, x, y, w, h, null);
		}
		finally
		{
			g2.setClip(previousClip);
		}
	}

	private static void drawCoverCentered(Graphics2D g2, BufferedImage image, Rectangle rect)
	{
		int sourceWidth = image.getWidth();
		int sourceHeight = image.getHeight();
		if (sourceWidth <= 0 || sourceHeight <= 0)
		{
			return;
		}

		double ratio = Math.max((double) rect.width / sourceWidth, (double) rect.height / sourceHeight);
		int w = Math.max(1, (int) Math.round(sourceWidth * ratio));
		int h = Math.max(1, (int) Math.round(sourceHeight * ratio));
		int x = rect.x + (rect.width - w) / 2;
		int y = rect.y + (rect.height - h) / 2;

		java.awt.Shape previousClip = g2.getClip();
		try
		{
			g2.setClip(rect);
			g2.drawImage(image, x, y, w, h, null);
		}
		finally
		{
			g2.setClip(previousClip);
		}
	}

	private static void drawImageSection(Graphics2D g2, Rectangle imageRect,
		CardVisualCatalog.CardVisual card, BufferedImage linkedImage)
	{
		if (linkedImage != null)
		{
			drawFitCentered(g2, linkedImage, inset(imageRect, 4));
			return;
		}

		String imageUrl = card == null ? null : card.imageUrl();
		String artText = (imageUrl != null && !imageUrl.trim().isEmpty()) ? "Artwork unavailable" : "No artwork";
		drawCenteredText(g2, imageRect, artText, FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR);
	}

	private static Rectangle inset(Rectangle r, int pad)
	{
		return new Rectangle(r.x + pad, r.y + pad, Math.max(1, r.width - (pad * 2)), Math.max(1, r.height - (pad * 2)));
	}

	private static int pct(int total, double fraction)
	{
		return Math.max(1, (int) Math.round(total * fraction));
	}

	private static void enableQuality(Graphics2D g2)
	{
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
	}

	/** Tier label (Common … Godly) from the accent color used on card frames, matching sidebar / pack reveal. */
	public static String tierLabelForRarityColor(Color color)
	{
		return rarityName(color);
	}

	/** Same score basis as OSRS TCG pack rolls and sidebar lists. */
	public static double cardDisplayScore(CardVisualCatalog.CardVisual card)
	{
		return card == null ? 0.0d : card.score();
	}

	private static String rarityName(Color color)
	{
		if (color == null)
		{
			return "Common";
		}

		if (matches(color, 0xF2C94C))
		{
			return "Godly";
		}
		if (matches(color, 0xFF6EC7))
		{
			return "Mythic";
		}
		if (matches(color, 0xE74C3C))
		{
			return "Legendary";
		}
		if (matches(color, 0x9B59B6))
		{
			return "Epic";
		}
		if (matches(color, 0x3498DB))
		{
			return "Rare";
		}
		if (matches(color, 0x2ECC71))
		{
			return "Uncommon";
		}
		return "Common";
	}

	private static boolean matches(Color color, int rgb)
	{
		return color.getRGB() == new Color(rgb).getRGB();
	}

	private static String valueOrFallback(String value, String fallback)
	{
		return (value == null || value.trim().isEmpty()) ? fallback : value.trim();
	}

	private static String formatScore(CardVisualCatalog.CardVisual card, boolean foilAdjusted)
	{
		if (card == null)
		{
			return "-";
		}
		double score = card.score();
		long displayed = foilAdjusted && score > 0.0d ? Math.round(Math.pow(score, 1.1d)) : Math.round(score);
		return formatNumber(displayed);
	}

	private static String formatNumber(long value)
	{
		String sign = value < 0 ? "-" : "";
		String digits = Long.toString(Math.abs(value));
		StringBuilder output = new StringBuilder();
		for (int i = 0; i < digits.length(); i++)
		{
			if (i > 0 && (digits.length() - i) % 3 == 0)
			{
				output.append(' ');
			}
			output.append(digits.charAt(i));
		}
		return sign + output;
	}

	private static Color blend(Color base, Color accent, float accentWeight)
	{
		float w = Math.max(0f, Math.min(1f, accentWeight));
		int r = Math.round(base.getRed() * (1f - w) + accent.getRed() * w);
		int g = Math.round(base.getGreen() * (1f - w) + accent.getGreen() * w);
		int b = Math.round(base.getBlue() * (1f - w) + accent.getBlue() * w);
		return new Color(clamp255(r), clamp255(g), clamp255(b));
	}

	private static int clamp255(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

	private static Color safeColor(Color color)
	{
		return color == null ? Color.WHITE : color;
	}

	private static String ellipsizeToWidth(String text, FontMetrics fm, int maxWidth)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		String ellipsis = "...";
		int ellipsisWidth = fm.stringWidth(ellipsis);
		if (ellipsisWidth >= maxWidth)
		{
			return "";
		}

		StringBuilder out = new StringBuilder();
		for (int i = 0; i < text.length(); i++)
		{
			char ch = text.charAt(i);
			if (fm.stringWidth(out.toString() + ch) + ellipsisWidth > maxWidth)
			{
				break;
			}
			out.append(ch);
		}
		return out + ellipsis;
	}

	/** Image band inside a drawn card face (below title, above tier line). */
	private static Rectangle cardImageAreaBounds(Rectangle cardBounds)
	{
		if (cardBounds == null || cardBounds.width <= 0 || cardBounds.height <= 0)
		{
			return null;
		}
		int ft = frameThicknessFor(cardBounds);
		Rectangle inner = inset(cardBounds, ft + 1);
		int titleH = pct(inner.height, 0.10d);
		int imageH = pct(inner.height, 0.40d);
		return new Rectangle(inner.x, inner.y + titleH, inner.width, imageH);
	}

	/** Lock badge for locked collection copies (top-right of the card image area). */
	public static void drawLockBadge(Graphics2D g2, Rectangle cardBounds)
	{
		if (g2 == null || cardBounds == null || LOCK_BADGE_IMAGE == null)
		{
			return;
		}
		Rectangle imageR = cardImageAreaBounds(cardBounds);
		if (imageR == null || imageR.width <= 0 || imageR.height <= 0)
		{
			return;
		}

		int pad = Math.max(2, imageR.width / 20);
		int maxDim = Math.max(8, Math.min(imageR.width, imageR.height) / 4);
		int srcW = LOCK_BADGE_IMAGE.getWidth();
		int srcH = LOCK_BADGE_IMAGE.getHeight();
		if (srcW <= 0 || srcH <= 0)
		{
			return;
		}
		double ratio = Math.min((double) maxDim / srcW, (double) maxDim / srcH);
		int w = Math.max(1, (int) Math.round(srcW * ratio));
		int h = Math.max(1, (int) Math.round(srcH * ratio));
		int x = imageR.x + imageR.width - w - pad;
		int y = imageR.y + pad;
		g2.drawImage(LOCK_BADGE_IMAGE, x, y, w, h, null);
	}
}

package com.groupmantcg;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/** Supported, read-only bridge to OSRS TCG's public collection message API. */
@Singleton
class OsrsTcgInteropService
{
	static final String NAMESPACE = "osrstcg";
	static final String QUERY = "query-owned-names";
	static final String REPLY = "owned-names";
	static final String CHANGED = "owned-names-changed";
	private static final String KEY_OWNED_NAMES = "ownedNames";
	private static final String KEY_OWNED_FOIL_NAMES = "ownedFoilNames";
	private static final String KEY_GROUP_KEY = "groupKey";
	private static final int QUERY_INTERVAL_TICKS = 100;

	private final EventBus eventBus;
	private Snapshot snapshot = Snapshot.unavailable();
	private InferredPack inferredPack;
	private int ticksUntilQuery;
	private boolean started;

	@Inject
	OsrsTcgInteropService(EventBus eventBus)
	{
		this.eventBus = eventBus;
	}

	synchronized void start()
	{
		started = true;
		ticksUntilQuery = 0;
	}

	synchronized void stop()
	{
		started = false;
		snapshot = Snapshot.unavailable();
		inferredPack = null;
	}

	void onTick()
	{
		synchronized (this)
		{
			if (!started || ticksUntilQuery-- > 0)
			{
				return;
			}
			ticksUntilQuery = QUERY_INTERVAL_TICKS;
		}
		eventBus.post(new PluginMessage(NAMESPACE, QUERY));
	}

	synchronized void profileChanged()
	{
		snapshot = Snapshot.unavailable();
		inferredPack = null;
		ticksUntilQuery = 0;
	}

	synchronized Snapshot snapshot()
	{
		return snapshot;
	}

	synchronized InferredPack drainInferredPack()
	{
		InferredPack result = inferredPack;
		inferredPack = null;
		return result;
	}

	/** Returns true when an authoritative collection snapshot changed. */
	synchronized boolean accept(PluginMessage event)
	{
		if (!started || event == null || !NAMESPACE.equals(event.getNamespace())
			|| (!REPLY.equals(event.getName()) && !CHANGED.equals(event.getName())))
		{
			return false;
		}
		Map<String, Object> data = event.getData();
		if (data == null || !(data.get(KEY_OWNED_NAMES) instanceof List))
		{
			return false;
		}
		Map<String, String> owned = readNames((List<?>) data.get(KEY_OWNED_NAMES));
		if (owned == null)
		{
			return false;
		}
		// OSRS TCG can reply before its cloud collection has loaded. Its later CHANGED push is
		// authoritative, including when the real collection is legitimately empty.
		Object groupKey = data.get(KEY_GROUP_KEY);
		boolean cloudReady = groupKey instanceof String && !((String) groupKey).trim().isEmpty();
		if (REPLY.equals(event.getName()) && owned.isEmpty() && !cloudReady
			&& (!snapshot.available() || !snapshot.ownedNames().isEmpty()))
		{
			return false;
		}

		boolean foilDataAvailable = data.containsKey(KEY_OWNED_FOIL_NAMES);
		Set<String> foils = Collections.emptySet();
		if (foilDataAvailable)
		{
			Object value = data.get(KEY_OWNED_FOIL_NAMES);
			if (!(value instanceof List))
			{
				return false;
			}
			Map<String, String> parsedFoils = readNames((List<?>) value);
			if (parsedFoils == null)
			{
				return false;
			}
			foils = parsedFoils.keySet();
		}
		Snapshot updated = new Snapshot(owned, foils, foilDataAvailable, true);
		if (CHANGED.equals(event.getName()) && snapshot.available())
		{
			inferredPack = inferPack(snapshot, updated);
		}
		boolean changed = !updated.equals(snapshot);
		snapshot = updated;
		return changed;
	}

	private static InferredPack inferPack(Snapshot previous, Snapshot current)
	{
		Map<String, CardDelta> gained = new LinkedHashMap<>();
		for (Map.Entry<String, String> owned : current.ownedNames().entrySet())
		{
			if (!previous.ownedNames().containsKey(owned.getKey()))
			{
				gained.put(owned.getKey(), new CardDelta(owned.getValue(),
					current.foilNames().contains(owned.getKey())));
			}
		}
		if (current.foilDataAvailable())
		{
			for (String foil : current.foilNames())
			{
				if (!previous.foilNames().contains(foil) && !gained.containsKey(foil))
				{
					String displayName = current.ownedNames().get(foil);
					if (displayName != null)
					{
						gained.put(foil, new CardDelta(displayName, true));
					}
				}
			}
		}
		if (gained.isEmpty() || gained.size() > 5)
		{
			return null;
		}
		return new InferredPack(new java.util.ArrayList<>(gained.values()),
			System.currentTimeMillis());
	}

	private static Map<String, String> readNames(List<?> values)
	{
		Map<String, String> result = new LinkedHashMap<>();
		for (Object value : values)
		{
			if (!(value instanceof String))
			{
				return null;
			}
			String displayName = ((String) value).trim();
			if (!displayName.isEmpty())
			{
				result.putIfAbsent(displayName.toLowerCase(Locale.ROOT), displayName);
			}
		}
		return result;
	}

	static final class Snapshot
	{
		private final Map<String, String> ownedNames;
		private final Set<String> foilNames;
		private final boolean foilDataAvailable;
		private final boolean available;

		private Snapshot(Map<String, String> ownedNames, Set<String> foilNames,
			boolean foilDataAvailable, boolean available)
		{
			this.ownedNames = Collections.unmodifiableMap(new LinkedHashMap<>(ownedNames));
			this.foilNames = Collections.unmodifiableSet(new LinkedHashSet<>(foilNames));
			this.foilDataAvailable = foilDataAvailable;
			this.available = available;
		}

		static Snapshot unavailable()
		{
			return new Snapshot(Collections.emptyMap(), Collections.emptySet(), false, false);
		}

		Map<String, String> ownedNames() { return ownedNames; }
		Set<String> foilNames() { return foilNames; }
		boolean foilDataAvailable() { return foilDataAvailable; }
		boolean available() { return available; }

		@Override
		public boolean equals(Object other)
		{
			if (this == other) return true;
			if (!(other instanceof Snapshot)) return false;
			Snapshot that = (Snapshot) other;
			return foilDataAvailable == that.foilDataAvailable && available == that.available
				&& ownedNames.equals(that.ownedNames) && foilNames.equals(that.foilNames);
		}

		@Override
		public int hashCode()
		{
			return java.util.Objects.hash(ownedNames, foilNames, foilDataAvailable, available);
		}
	}

	static final class InferredPack
	{
		private final List<CardDelta> cards;
		private final long inferredAt;

		private InferredPack(List<CardDelta> cards, long inferredAt)
		{
			this.cards = Collections.unmodifiableList(new java.util.ArrayList<>(cards));
			this.inferredAt = inferredAt;
		}

		List<CardDelta> cards() { return cards; }
		long inferredAt() { return inferredAt; }
	}

	static final class CardDelta
	{
		private final String displayName;
		private final boolean foil;

		private CardDelta(String displayName, boolean foil)
		{
			this.displayName = displayName;
			this.foil = foil;
		}

		String displayName() { return displayName; }
		boolean foil() { return foil; }
	}
}

package com.groupmantcg;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

/** Replaces OSRS TCG copy IDs before they are sent to a group server. */
final class PrivacyIdentifiers
{
	private PrivacyIdentifiers()
	{
	}

	static String collectionInstance(String instanceId)
	{
		return "i_" + digest("instance\u0000" + (instanceId == null ? "" : instanceId));
	}

	private static String digest(String value)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] bytes = digest.digest(value.getBytes(StandardCharsets.UTF_8));
			return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
		}
		catch (NoSuchAlgorithmException ex)
		{
			throw new IllegalStateException(ex);
		}
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Data-driven processing recipes matched against item and production-interface clicks. */
@Slf4j
@Singleton
class RecipeRuleCatalog
{
	static final String ITEM_ON_ITEM = "item-on-item";
	static final String ITEM_ON_OBJECT = "item-on-object";
	static final String INTERFACE = "interface";
	static final String SPELL_ON_ITEM = "spell-on-item";
	private static final String ANY_TARGET = "*";
	private static final Set<String> COLOURED_LOGS = new HashSet<>(Arrays.asList(
		"blue logs", "green logs", "red logs", "purple logs", "white logs"));

	private Map<String, Rule> rules = Collections.emptyMap();

	@Inject
	RecipeRuleCatalog(Gson gson)
	{
		load(gson);
	}

	Rule find(String kind, String name, String target)
	{
		if (kind == null || name == null)
		{
			return null;
		}
		String cleanKind = normalize(kind);
		String cleanName = normalizeDose(name);
		String cleanTarget = target == null ? ANY_TARGET : normalizeDose(target);
		Rule rule = rules.get(key(cleanKind, cleanName, cleanTarget));
		return rule != null || ANY_TARGET.equals(cleanTarget)
			? rule : rules.get(key(cleanKind, cleanName, ANY_TARGET));
	}

	int size()
	{
		return rules.size();
	}

	private void load(Gson gson)
	{
		try (InputStream input = getClass().getResourceAsStream("/recipe_nodes.json"))
		{
			if (input == null)
			{
				log.warn("Missing recipe_nodes.json; processing restrictions are unavailable");
				return;
			}
			Snapshot snapshot = gson.fromJson(new InputStreamReader(input, StandardCharsets.UTF_8), Snapshot.class);
			if (snapshot == null || snapshot.recipes == null)
			{
				return;
			}
			Map<String, Rule> loaded = new HashMap<>();
			for (Recipe recipe : snapshot.recipes)
			{
				if (recipe == null || recipe.category == null || recipe.trigger == null
					|| recipe.trigger.kind == null || recipe.trigger.name == null)
				{
					continue;
				}
				List<CardRequirement> inputs = new ArrayList<>();
				if (recipe.inputs != null)
				{
					for (List<String> inputGroup : recipe.inputs)
					{
						CardRequirement requirement = CardRequirement.create(inputGroup, null);
						if (requirement != null)
						{
							inputs.add(requirement);
						}
					}
				}
				String kind = normalize(recipe.trigger.kind);
				String name = normalizeDose(recipe.trigger.name);
				List<String> targets = recipe.trigger.targets == null || recipe.trigger.targets.isEmpty()
					? Collections.singletonList(ANY_TARGET) : recipe.trigger.targets;
				for (String target : targets)
				{
					String cleanTarget = target == null ? ANY_TARGET : normalizeDose(target);
					Rule rule = new Rule(normalize(recipe.category), inputs, recipe.output,
						"firemaking".equals(normalize(recipe.category)) && COLOURED_LOGS.contains(cleanTarget),
						recipe.crushable);
					loaded.put(key(kind, name, cleanTarget), rule);
					if (SPELL_ON_ITEM.equals(kind))
					{
						loaded.put(key(kind, cleanTarget, ANY_TARGET), rule);
					}
					if (INTERFACE.equals(kind))
					{
						loaded.put(key(kind, name, ANY_TARGET), rule);
					}
				}
			}
			rules = Collections.unmodifiableMap(loaded);
			log.info("Loaded {} processing recipe rules", rules.size());
		}
		catch (Exception ex)
		{
			log.warn("Unable to load processing recipe rules", ex);
		}
	}

	private static String key(String kind, String name, String target)
	{
		return kind + '|' + name + '|' + target;
	}

	private static String normalize(String value)
	{
		return EntityCardCatalog.normalize(value);
	}

	private static String normalizeDose(String value)
	{
		return normalize(value).replaceFirst("\\([1-4]\\)$", "");
	}

	static final class Rule
	{
		private final String category;
		private final List<CardRequirement> inputs;
		private final String outputDisplay;
		private final String outputNormalized;
		private final boolean colouredEventLog;
		private final boolean crushable;

		private Rule(String category, List<CardRequirement> inputs, String output,
			boolean colouredEventLog, boolean crushable)
		{
			this.category = category;
			this.inputs = Collections.unmodifiableList(new ArrayList<>(inputs));
			this.outputDisplay = output == null ? null : output.trim();
			this.outputNormalized = output == null ? null : output.trim().toLowerCase(Locale.ROOT);
			this.colouredEventLog = colouredEventLog;
			this.crushable = crushable;
		}

		String category()
		{
			return category;
		}

		boolean isColouredEventLog()
		{
			return colouredEventLog;
		}

		boolean isCrushable()
		{
			return crushable;
		}

		List<String> missing(Set<String> owned, boolean requireInputs, boolean requireOutput,
			boolean skipTinderbox)
		{
			List<String> missing = new ArrayList<>();
			if (requireInputs)
			{
				for (CardRequirement input : inputs)
				{
					if (skipTinderbox && input.contains("tinderbox"))
					{
						continue;
					}
					if (!input.isSatisfied(owned))
					{
						missing.add(input.display());
					}
				}
			}
			if (requireOutput && outputNormalized != null && !owned.contains(outputNormalized))
			{
				missing.add(outputDisplay);
			}
			return missing;
		}
	}

	private static class Snapshot
	{
		List<Recipe> recipes;
	}

	private static class Recipe
	{
		String category;
		List<List<String>> inputs;
		String output;
		boolean crushable;
		Trigger trigger;
	}

	private static class Trigger
	{
		String kind;
		String name;
		List<String> targets;
	}
}

package com.groupmantcg;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

/** Chooses between the player's cards and the shared server collection. */
@Slf4j
@Singleton
class SharedCollectionService
{
	private static final String CACHE_KEY = "sharedCollectionV1";
	private static final int REFRESH_TICKS = 5;
	private static final DateTimeFormatter PULL_DATE = DateTimeFormatter.ofPattern("d MMM uuuu")
		.withZone(ZoneId.systemDefault());

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final GroupmanTcgConfig config;
	private final LocalCollection localCollection;
	private final CardBitsetIndex index;
	private final GroupCacheCodec cacheCodec;

	private volatile Set<String> sharedCards = Collections.emptySet();
	private volatile Map<String, MemberCollection> memberCollections = Collections.emptyMap();
	private volatile GroupSyncStatus status = soloStatus(0);
	private String groupId;
	private String groupName;
	private String localPlayerName;
	private boolean approved;
	private int ticks;
	private boolean started;

	@Inject
	SharedCollectionService(Client client, ClientThread clientThread, ConfigManager configManager,
		GroupmanTcgConfig config, LocalCollection localCollection, CardBitsetIndex index,
		GroupCacheCodec cacheCodec)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.config = config;
		this.localCollection = localCollection;
		this.index = index;
		this.cacheCodec = cacheCodec;
	}

	void start()
	{
		started = true;
		requestRefresh();
	}

	void stop()
	{
		started = false;
		clearServerState();
		status = soloStatus(localCollection.getCards().size());
	}

	Set<String> cards()
	{
		return config.collectionMode() == CollectionMode.GROUP_IRONMAN && status.isActive()
			? sharedCards : localCollection.getCards();
	}

	GroupSyncStatus status()
	{
		return status;
	}

	Map<String, Set<String>> memberCollections()
	{
		List<MemberCollection> sorted = new ArrayList<>(memberCollections.values());
		sorted.sort(Comparator.comparing(member -> member.displayName, String.CASE_INSENSITIVE_ORDER));
		Map<String, Set<String>> result = new LinkedHashMap<>();
		for (MemberCollection member : sorted)
		{
			result.put(member.displayName, member.cards);
		}
		return Collections.unmodifiableMap(result);
	}

	CollectionAlbumSnapshot collectionAlbum(String collectionKey, String displayName)
	{
		String requestedKey = collectionKey == null ? "" : EntityCardCatalog.normalize(collectionKey);
		String localKey = localPlayerName == null ? "" : EntityCardCatalog.normalize(localPlayerName);
		if (!requestedKey.isEmpty())
		{
			if (requestedKey.equals(localKey))
			{
				return localAlbum(displayName);
			}
			MemberCollection member = memberCollections.get(requestedKey);
			if (member == null)
			{
				return new CollectionAlbumSnapshot(displayName, Collections.emptySet(), Collections.emptyMap());
			}
			Map<String, CollectionAlbumSnapshot.Ownership> ownership = new HashMap<>();
			addHostedOwnership(ownership, member);
			return new CollectionAlbumSnapshot(member.displayName, member.cards, ownership);
		}

		if (config.collectionMode() != CollectionMode.GROUP_IRONMAN || !status.isActive())
		{
			return localAlbum(displayName);
		}

		Map<String, CollectionAlbumSnapshot.Ownership> ownership = new HashMap<>();
		for (Map.Entry<String, MemberCollection> entry : memberCollections.entrySet())
		{
			if (!entry.getKey().equals(localKey))
			{
				addHostedOwnership(ownership, entry.getValue());
			}
		}
		addLocalOwnership(ownership);
		return new CollectionAlbumSnapshot(displayName, sharedCards, ownership);
	}

	private CollectionAlbumSnapshot localAlbum(String displayName)
	{
		Map<String, CollectionAlbumSnapshot.Ownership> ownership = new HashMap<>();
		addLocalOwnership(ownership);
		return new CollectionAlbumSnapshot(displayName, localCollection.getCards(), ownership);
	}

	private void addLocalOwnership(Map<String, CollectionAlbumSnapshot.Ownership> destination)
	{
		for (LocalCollection.CardInstance instance : localCollection.snapshot().instances())
		{
			CollectionAlbumSnapshot.Ownership copy = instance.foil()
				? new CollectionAlbumSnapshot.Ownership(0, 1)
				: new CollectionAlbumSnapshot.Ownership(1, 0);
			destination.merge(instance.normalizedName(), copy,
				CollectionAlbumSnapshot.Ownership::plus);
		}
	}

	private static void addHostedOwnership(
		Map<String, CollectionAlbumSnapshot.Ownership> destination, MemberCollection member)
	{
		for (String cardName : member.cards)
		{
			String normalized = EntityCardCatalog.normalize(cardName);
			HostedCollectionSnapshot.CardDetails detail = member.details.get(normalized);
			CollectionAlbumSnapshot.Ownership copies;
			if (detail == null || detail.copies() <= 0)
			{
				copies = new CollectionAlbumSnapshot.Ownership(1, 0);
			}
			else
			{
				int foils = Math.max(0, Math.min(detail.foilCopies(), detail.copies()));
				copies = new CollectionAlbumSnapshot.Ownership(detail.copies() - foils, foils);
			}
			destination.merge(normalized, copies, CollectionAlbumSnapshot.Ownership::plus);
		}
	}

	List<HostedCollectionSnapshot.RecentCard> recentCards(String collectionKey, int limit)
	{
		String requestedKey = collectionKey == null ? "" : EntityCardCatalog.normalize(collectionKey);
		String localKey = localPlayerName == null ? "" : EntityCardCatalog.normalize(localPlayerName);
		if (!requestedKey.isEmpty())
		{
			if (requestedKey.equals(localKey))
			{
				return recentLocalCards(localPlayerName, limit);
			}
			MemberCollection member = memberCollections.get(requestedKey);
			return member == null ? Collections.emptyList()
				: HostedCollectionSnapshot.newestCards(member.recentCards, limit);
		}

		if (config.collectionMode() != CollectionMode.GROUP_IRONMAN || !status.isActive())
		{
			return recentLocalCards(localPlayerName, limit);
		}

		List<HostedCollectionSnapshot.RecentCard> combined = new ArrayList<>();
		for (Map.Entry<String, MemberCollection> entry : memberCollections.entrySet())
		{
			if (!entry.getKey().equals(localKey))
			{
				combined.addAll(entry.getValue().recentCards);
			}
		}
		combined.addAll(recentLocalCards(localPlayerName, limit));
		return HostedCollectionSnapshot.newestCards(combined, limit);
	}

	private List<HostedCollectionSnapshot.RecentCard> recentLocalCards(String owner, int limit)
	{
		List<HostedCollectionSnapshot.RecentCard> recent = new ArrayList<>();
		for (LocalCollection.CardInstance instance : localCollection.snapshot().instances())
		{
			if (instance.pulledAt() <= 0L || isDebugPull(instance.pulledBy()))
			{
				continue;
			}
			recent.add(new HostedCollectionSnapshot.RecentCard(instance.id(), instance.displayName(),
				instance.foil(), instance.pulledAt(), owner));
		}
		return HostedCollectionSnapshot.newestCards(recent, limit);
	}

	private static boolean isDebugPull(String pulledBy)
	{
		return pulledBy != null && pulledBy.regionMatches(true, 0, "DEBUG_", 0, "DEBUG_".length());
	}

	List<String> ownersOf(Set<String> cardNames)
	{
		List<String> owners = new ArrayList<>();
		for (MemberCollection member : memberCollections.values())
		{
			for (String cardName : cardNames)
			{
				if (member.cards.contains(cardName))
				{
					owners.add(member.displayName);
					break;
				}
			}
		}
		owners.sort(String.CASE_INSENSITIVE_ORDER);
		return owners;
	}

	List<String> ownershipDetails(Set<String> cardNames)
	{
		List<String> details = new ArrayList<>();
		String localKey = localPlayerName == null ? null : EntityCardCatalog.normalize(localPlayerName);
		for (String owner : ownersOf(cardNames))
		{
			String ownerKey = EntityCardCatalog.normalize(owner);
			if (localKey != null && localKey.equals(ownerKey))
			{
				LocalCollection.CardSummary summary = bestLocalSummary(cardNames);
				if (summary != null)
				{
					details.add(describe(owner, summary.copies(), summary.foilCopies(), summary.debugCopies(),
						summary.pulledBy(), summary.firstPulledAt()));
					continue;
				}
			}

			MemberCollection member = memberCollections.get(ownerKey);
			HostedCollectionSnapshot.CardDetails hosted = bestHostedSummary(member, cardNames);
			if (hosted != null)
			{
				details.add(describe(owner, hosted.copies(), hosted.foilCopies(), hosted.debugCopies(),
					Collections.emptySet(), hosted.firstPulledAt()));
			}
			else
			{
				details.add(owner);
			}
		}
		return details;
	}

	private LocalCollection.CardSummary bestLocalSummary(Set<String> cardNames)
	{
		LocalCollection.CardSummary summary = null;
		for (String cardName : cardNames)
		{
			LocalCollection.CardSummary candidate = localCollection.summary(cardName);
			if (candidate != null && (summary == null || candidate.copies() > summary.copies()))
			{
				summary = candidate;
			}
		}
		return summary;
	}

	private static HostedCollectionSnapshot.CardDetails bestHostedSummary(MemberCollection member,
		Set<String> cardNames)
	{
		if (member == null)
		{
			return null;
		}
		HostedCollectionSnapshot.CardDetails hosted = null;
		for (String cardName : cardNames)
		{
			HostedCollectionSnapshot.CardDetails candidate = member.details.get(cardName);
			if (candidate != null && (hosted == null || candidate.copies() > hosted.copies()))
			{
				hosted = candidate;
			}
		}
		return hosted;
	}

	private static String describe(String owner, int copies, int foils, int debug,
		Set<String> pulledBy, long firstPulledAt)
	{
		StringBuilder detail = new StringBuilder(owner).append(": ").append(copies)
			.append(copies == 1 ? " copy" : " copies");
		if (foils > 0)
		{
			detail.append(", ").append(foils).append(" foil");
		}
		if (debug > 0)
		{
			detail.append(", ").append(debug).append(" debug grant").append(debug == 1 ? "" : "s");
		}
		if (!pulledBy.isEmpty())
		{
			detail.append(", pulled by ").append(String.join(" / ", pulledBy));
		}
		if (firstPulledAt > 0L)
		{
			detail.append(" on ").append(PULL_DATE.format(Instant.ofEpochMilli(firstPulledAt)));
		}
		return detail.toString();
	}

	void onTick()
	{
		if (started && ++ticks % REFRESH_TICKS == 0)
		{
			refresh();
		}
	}

	void localCollectionChanged()
	{
		localCollection.invalidate();
		requestRefresh();
	}

	void contextChanged()
	{
		requestRefresh();
	}

	void profileChanged()
	{
		localCollection.invalidate();
		clientThread.invokeLater(() ->
		{
			clearServerState();
			refresh();
		});
	}

	void hostedContextChanged(String incomingGroupId, String incomingGroupName,
		String incomingPlayerName, boolean incomingApproved)
	{
		clientThread.invokeLater(() -> applyHostedContext(incomingGroupId, incomingGroupName,
			incomingPlayerName, incomingApproved));
	}

	private void applyHostedContext(String incomingGroupId, String incomingGroupName,
		String incomingPlayerName, boolean incomingApproved)
	{
		if (!started)
		{
			return;
		}
		if (incomingGroupId == null || incomingGroupId.trim().isEmpty())
		{
			clearServerState();
			refresh();
			return;
		}
		String cleanGroupId = incomingGroupId.trim();
		if (!cleanGroupId.equals(groupId))
		{
			groupId = cleanGroupId;
			LoadedCache loaded = loadCache();
			sharedCards = loaded.sharedCards;
			memberCollections = loaded.memberCollections;
		}
		groupName = incomingGroupName == null || incomingGroupName.trim().isEmpty()
			? "Group server" : incomingGroupName.trim();
		localPlayerName = incomingPlayerName == null ? null : incomingPlayerName.trim();
		approved = incomingApproved;
		refresh();
	}

	void hostedSnapshotReceived(HostedCollectionSnapshot snapshot)
	{
		if (!started || snapshot == null)
		{
			return;
		}
		if (!snapshot.groupId().equals(groupId))
		{
			applyHostedContext(snapshot.groupId(), snapshot.groupName(), snapshot.localPlayerName(), true);
		}
		else
		{
			groupName = snapshot.groupName();
			localPlayerName = snapshot.localPlayerName();
			approved = true;
		}

		int previousSize = sharedCards.size();
		if (!snapshot.members().isEmpty())
		{
			Map<String, MemberCollection> updated = new HashMap<>();
			Map<String, List<HostedCollectionSnapshot.RecentCard>> recentByMember = new HashMap<>();
			for (Map.Entry<String, List<HostedCollectionSnapshot.RecentCard>> entry
				: snapshot.recentCards().entrySet())
			{
				recentByMember.put(EntityCardCatalog.normalize(entry.getKey()), entry.getValue());
			}
			for (Map.Entry<String, Map<String, HostedCollectionSnapshot.CardDetails>> entry
				: snapshot.members().entrySet())
			{
				if (entry.getKey() == null || entry.getKey().trim().isEmpty())
				{
					continue;
				}
				String shownName = entry.getKey().trim();
				String memberKey = EntityCardCatalog.normalize(shownName);
				updated.put(memberKey, new MemberCollection(shownName, entry.getValue().keySet(),
					entry.getValue(), recentByMember.getOrDefault(memberKey, Collections.emptyList())));
			}
			memberCollections = Collections.unmodifiableMap(updated);
		}

		Set<String> combined = new HashSet<>(sharedCards);
		combined.addAll(snapshot.unlocks());
		for (MemberCollection member : memberCollections.values())
		{
			combined.addAll(member.cards);
		}
		if (config.collectionMode() == CollectionMode.GROUP_IRONMAN)
		{
			combined.addAll(localCollection.getCards());
		}
		setSharedCards(combined);
		persist();
		refresh();

		int added = sharedCards.size() - previousSize;
		if (added > 0 && config.collectionMode() == CollectionMode.GROUP_IRONMAN && config.syncMessages())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"[Group TCG] The server collection gained " + added + " unlock" + (added == 1 ? "" : "s") + ".",
				null);
		}
	}

	private void requestRefresh()
	{
		clientThread.invokeLater(this::refresh);
	}

	private void refresh()
	{
		Set<String> local = localCollection.getCards();
		if (!started || config.collectionMode() == CollectionMode.SOLO)
		{
			status = soloStatus(local.size());
			return;
		}
		if (groupId == null || !approved)
		{
			status = inactiveStatus(local.size(), "Join a group server and wait for host approval");
			return;
		}

		boolean changed = false;
		if (localPlayerName != null && !localPlayerName.isEmpty())
		{
			changed = setMemberCollection(localPlayerName, local);
		}
		Set<String> combined = new HashSet<>(sharedCards);
		changed |= combined.addAll(local);
		if (changed)
		{
			setSharedCards(combined);
			persist();
		}
		status = new GroupSyncStatus(true, true, true, groupName, sharedCards.size(),
			memberCollections.size(), memberCollections.size(), "Using cards shared through the group server");
	}

	private LoadedCache loadCache()
	{
		try
		{
			String json = configManager.getRSProfileConfiguration(GroupmanTcgConfig.GROUP, CACHE_KEY);
			GroupCacheCodec.Cache cache = cacheCodec.decode(json);
			if (cache == null || !groupId.equals(cache.groupKey)
				|| !index.fingerprint().equals(cache.catalogFingerprint))
			{
				return LoadedCache.empty();
			}
			Map<String, MemberCollection> members = new HashMap<>();
			for (Map.Entry<String, String> entry : cache.memberUnlockBits.entrySet())
			{
				if (entry.getKey() != null && entry.getValue() != null && !entry.getKey().trim().isEmpty())
				{
					String displayName = entry.getKey().trim();
					members.put(EntityCardCatalog.normalize(displayName),
						new MemberCollection(displayName, index.decode(entry.getValue()), Collections.emptyMap(),
							Collections.emptyList()));
				}
			}
			return new LoadedCache(index.decode(cache.unlockBits), members);
		}
		catch (Exception ex)
		{
			log.debug("Unable to load server collection cache", ex);
			return LoadedCache.empty();
		}
	}

	private void persist()
	{
		if (groupId == null)
		{
			return;
		}
		Map<String, String> memberBits = new LinkedHashMap<>();
		for (MemberCollection member : memberCollections.values())
		{
			memberBits.put(member.displayName, index.encode(member.cards));
		}
		configManager.setRSProfileConfiguration(GroupmanTcgConfig.GROUP, CACHE_KEY,
			cacheCodec.encode(groupId, index.fingerprint(), index.encode(sharedCards), memberBits));
	}

	private boolean setMemberCollection(String displayName, Set<String> cards)
	{
		String shownName = displayName.trim();
		String key = EntityCardCatalog.normalize(shownName);
		MemberCollection current = memberCollections.get(key);
		Map<String, HostedCollectionSnapshot.CardDetails> details = new HashMap<>();
		List<HostedCollectionSnapshot.RecentCard> recentCards = new ArrayList<>();
		if (current != null)
		{
			for (Map.Entry<String, HostedCollectionSnapshot.CardDetails> entry : current.details.entrySet())
			{
				if (cards.contains(entry.getKey()))
				{
					details.put(entry.getKey(), entry.getValue());
				}
			}
			for (HostedCollectionSnapshot.RecentCard recent : current.recentCards)
			{
				if (cards.contains(EntityCardCatalog.normalize(recent.cardName())))
				{
					recentCards.add(recent);
				}
			}
		}
		if (current != null && current.displayName.equals(shownName) && current.cards.equals(cards)
			&& current.details.equals(details) && current.recentCards.equals(recentCards))
		{
			return false;
		}
		Map<String, MemberCollection> updated = new HashMap<>(memberCollections);
		updated.put(key, new MemberCollection(shownName, cards, details, recentCards));
		memberCollections = Collections.unmodifiableMap(updated);
		return true;
	}

	private void setSharedCards(Set<String> cards)
	{
		sharedCards = Collections.unmodifiableSet(new HashSet<>(cards));
	}

	private void clearServerState()
	{
		sharedCards = Collections.emptySet();
		memberCollections = Collections.emptyMap();
		groupId = null;
		groupName = null;
		localPlayerName = null;
		approved = false;
	}

	private static GroupSyncStatus inactiveStatus(int cards, String detail)
	{
		return new GroupSyncStatus(true, false, false, "", cards, 0, 0, detail);
	}

	private static GroupSyncStatus soloStatus(int cards)
	{
		return new GroupSyncStatus(false, true, false, "", cards, 0, 0,
			"Solo unlocks; server membership and Top Trumps remain available");
	}

	private static final class MemberCollection
	{
		private final String displayName;
		private final Set<String> cards;
		private final Map<String, HostedCollectionSnapshot.CardDetails> details;
		private final List<HostedCollectionSnapshot.RecentCard> recentCards;

		private MemberCollection(String displayName, Set<String> cards,
			Map<String, HostedCollectionSnapshot.CardDetails> details,
			List<HostedCollectionSnapshot.RecentCard> recentCards)
		{
			this.displayName = displayName;
			this.cards = Collections.unmodifiableSet(new HashSet<>(cards));
			this.details = Collections.unmodifiableMap(new HashMap<>(details));
			this.recentCards = HostedCollectionSnapshot.newestCards(recentCards, recentCards.size());
		}
	}

	private static final class LoadedCache
	{
		private final Set<String> sharedCards;
		private final Map<String, MemberCollection> memberCollections;

		private LoadedCache(Set<String> sharedCards, Map<String, MemberCollection> memberCollections)
		{
			this.sharedCards = Collections.unmodifiableSet(new HashSet<>(sharedCards));
			this.memberCollections = Collections.unmodifiableMap(new HashMap<>(memberCollections));
		}

		private static LoadedCache empty()
		{
			return new LoadedCache(Collections.emptySet(), Collections.emptyMap());
		}
	}
}

