package com.groupmantcg;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/** Routes menu interactions into the gathering and processing rule catalogs. */
@Singleton
class SkillRestrictionEngine
{
	enum Decision
	{
		NOT_APPLICABLE,
		ALLOWED,
		BLOCKED
	}

	private static final String SEPARATOR = " -> ";
	private static final Set<String> MAKE_VERBS = new HashSet<>(Arrays.asList(
		"smelt", "make", "craft", "smith", "string", "mix", "cook", "bake",
		"fletch", "spin", "fire", "create", "build", "upgrade"));

	private final Client client;
	private final ItemManager itemManager;
	private final GroupmanTcgConfig config;
	private final SharedCollectionService collection;
	private final InteractionRuleCatalog interactions;
	private final RecipeRuleCatalog recipes;
	private final FeedbackService feedback;

	@Inject
	SkillRestrictionEngine(Client client, ItemManager itemManager, GroupmanTcgConfig config,
		SharedCollectionService collection, InteractionRuleCatalog interactions,
		RecipeRuleCatalog recipes, FeedbackService feedback)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		this.collection = collection;
		this.interactions = interactions;
		this.recipes = recipes;
		this.feedback = feedback;
	}

	Decision handle(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		NPC npc = entry.getNpc();
		if (npc != null)
		{
			return handleNpc(event, npc);
		}

		MenuAction action = event.getMenuAction();
		if (action == null)
		{
			return Decision.NOT_APPLICABLE;
		}
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return checkInteraction(event, InteractionRuleCatalog.OBJECT,
					clean(event.getMenuTarget()), clean(event.getMenuOption()));
			case ITEM_USE_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GAME_OBJECT:
				return handleItemOnObject(event);
			case CC_OP:
			case CC_OP_LOW_PRIORITY:
				return handleWidgetOperation(event);
			case ITEM_USE_ON_ITEM:
			case WIDGET_USE_ON_ITEM:
			case WIDGET_TARGET_ON_WIDGET:
				return handleItemOnItem(event);
			default:
				return Decision.NOT_APPLICABLE;
		}
	}

	private Decision handleNpc(MenuOptionClicked event, NPC npc)
	{
		String name = npcName(npc);
		String option = clean(event.getMenuOption());
		if ("master farmer".equals(EntityCardCatalog.normalize(name)) && "pickpocket".equals(option))
		{
			return checkMasterFarmer(event);
		}
		return checkInteraction(event, InteractionRuleCatalog.NPC, name, option);
	}

	private Decision handleItemOnObject(MenuOptionClicked event)
	{
		String[] parts = splitTarget(event.getMenuTarget());
		if (parts == null)
		{
			return Decision.NOT_APPLICABLE;
		}
		Decision interaction = checkInteraction(event, InteractionRuleCatalog.ITEM_ON_OBJECT, parts[0], parts[1]);
		return interaction != Decision.NOT_APPLICABLE
			? interaction : checkRecipe(event, RecipeRuleCatalog.ITEM_ON_OBJECT, parts[0], parts[1]);
	}

	private Decision handleWidgetOperation(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		String option = clean(event.getMenuOption());
		int group = WidgetUtil.componentToInterface(entry.getParam1());
		if (group == InterfaceID.INVENTORY)
		{
			String itemName = itemName(event, entry);
			Decision interaction = checkInteraction(event, InteractionRuleCatalog.INVENTORY, itemName, option);
			if (interaction != Decision.NOT_APPLICABLE)
			{
				return interaction;
			}
			return "light".equals(option)
				? checkRecipe(event, RecipeRuleCatalog.ITEM_ON_ITEM, "Tinderbox", itemName)
				: Decision.NOT_APPLICABLE;
		}

		String product = clean(event.getMenuTarget());
		if (product.isEmpty())
		{
			return Decision.NOT_APPLICABLE;
		}
		if (group == InterfaceID.SKILLMULTI || group == InterfaceID.SMITHING || isMakeVerb(option))
		{
			Decision interaction = checkInteraction(event, InteractionRuleCatalog.INTERFACE,
				product, InteractionRuleCatalog.ANY_OPTION);
			return interaction != Decision.NOT_APPLICABLE
				? interaction : checkRecipe(event, RecipeRuleCatalog.INTERFACE, product, null);
		}
		return Decision.NOT_APPLICABLE;
	}

	private Decision handleItemOnItem(MenuOptionClicked event)
	{
		String[] parts = splitTarget(event.getMenuTarget());
		if (parts == null)
		{
			return Decision.NOT_APPLICABLE;
		}
		if (parts[0].toLowerCase(Locale.ROOT).startsWith("cast ") || selectedWidgetIsSpell())
		{
			return checkRecipe(event, RecipeRuleCatalog.SPELL_ON_ITEM, parts[1], null);
		}
		Decision forwards = checkRecipe(event, RecipeRuleCatalog.ITEM_ON_ITEM, parts[0], parts[1]);
		return forwards != Decision.NOT_APPLICABLE
			? forwards : checkRecipe(event, RecipeRuleCatalog.ITEM_ON_ITEM, parts[1], parts[0]);
	}

	private Decision checkMasterFarmer(MenuOptionClicked event)
	{
		List<String> required;
		switch (config.masterFarmer())
		{
			case BASIC:
				required = Arrays.asList("Coins", "Coin pouch");
				break;
			case ALL_SEEDS:
				required = interactions.masterFarmerSeeds();
				if (required.isEmpty())
				{
					required = Arrays.asList("Coins", "Coin pouch");
				}
				break;
			default:
				return Decision.NOT_APPLICABLE;
		}
		List<String> missing = missingCards(required);
		return consumeIfMissing(event, missing);
	}

	private Decision checkInteraction(MenuOptionClicked event, String kind, String name, String option)
	{
		InteractionRuleCatalog.Rule rule = interactions.find(kind, name, option);
		if (rule == null)
		{
			return Decision.NOT_APPLICABLE;
		}
		Evaluation evaluation = evaluation(rule.category());
		if (evaluation == null)
		{
			return Decision.ALLOWED;
		}
		List<String> missing = rule.missing(collection.cards(), evaluation.excludedRoles, evaluation.requireAll);
		return consumeIfMissing(event, missing);
	}

	private Evaluation evaluation(String category)
	{
		switch (category)
		{
			case "woodcutting": return config.woodcutting() ? Evaluation.full() : null;
			case "mining": return config.mining() ? Evaluation.full() : null;
			case "fishing": return anyAll(config.fishing());
			case "thieving-stalls": return anyAll(config.stalls());
			case "pickpocketing":
				if (config.pickpocketing() == SkillModes.Thieving.LOOT) return Evaluation.excluding("npc");
				return config.pickpocketing() == SkillModes.Thieving.NPC_AND_LOOT ? Evaluation.full() : null;
			case "cooking":
				if (config.cooking() == SkillModes.Cooking.COOKED) return Evaluation.excluding("burnt");
				return config.cooking() == SkillModes.Cooking.COOKED_AND_BURNT ? Evaluation.full() : null;
			case "runecrafting":
				if (config.runecrafting() == SkillModes.Runecrafting.TALISMAN) return Evaluation.excluding("rune");
				return config.runecrafting() == SkillModes.Runecrafting.TALISMAN_AND_RUNES ? Evaluation.full() : null;
			case "farming-rake":
				if (config.farmingRake() == SkillModes.FarmingRake.TOOLS) return Evaluation.excluding("weeds");
				return config.farmingRake() == SkillModes.FarmingRake.TOOLS_AND_WEEDS ? Evaluation.full() : null;
			case "farming-plant":
				switch (config.farmingPlant())
				{
					case TOOLS: return Evaluation.excluding("seed", "produce");
					case TOOLS_AND_SEEDS: return Evaluation.excluding("produce");
					case ALL: return Evaluation.full();
					default: return null;
				}
			case "farming-compost": return config.compost() ? Evaluation.full() : null;
			case "hunter-birds":
			case "hunter-butterflies": return hunterGear(config.hunterBirds(), "creature", "extra");
			case "hunter-implings":
				if (config.implings() == SkillModes.Implings.NET) return Evaluation.excluding("extra");
				return config.implings() == SkillModes.Implings.NET_AND_JAR ? Evaluation.full() : null;
			case "hunter-salamanders": return hunterGear(config.salamanders(), "creature");
			case "hunter-pitfalls": return hunterGear(config.pitfalls(), "creature");
			case "hunter-chins": return config.chinchompas() ? Evaluation.full() : null;
			case "hunter-rumours": return config.hunterRumours() ? Evaluation.full() : null;
			case "slayer": return slayerEvaluation();
			case "sailing-upgrades": return sailingEvaluation();
			case "sailing-salvage": return config.salvaging() ? Evaluation.full() : null;
			default: return Evaluation.full();
		}
	}

	private Evaluation slayerEvaluation()
	{
		Set<String> excluded = new HashSet<>();
		if (!config.slayerMasters()) excluded.add("master");
		if (!config.slayerMonsters()) excluded.add("monsters");
		if (!config.slayerMonsters() || !config.slayerSuperiors()) excluded.add("superiors");
		return excluded.contains("master") && excluded.contains("monsters") ? null : new Evaluation(excluded, false);
	}

	private Evaluation sailingEvaluation()
	{
		switch (config.sailingUpgrades())
		{
			case PARTS: return Evaluation.excluding("material", "large");
			case PARTS_AND_MATERIALS: return Evaluation.excluding("large");
			case ALL: return Evaluation.full();
			default: return null;
		}
	}

	private static Evaluation anyAll(SkillModes.AnyAll mode)
	{
		return mode == SkillModes.AnyAll.OFF ? null : new Evaluation(Collections.emptySet(), mode == SkillModes.AnyAll.ALL);
	}

	private static Evaluation hunterGear(SkillModes.HunterGear mode, String... optionalRoles)
	{
		if (mode == SkillModes.HunterGear.OFF) return null;
		return mode == SkillModes.HunterGear.GEAR ? Evaluation.excluding(optionalRoles) : Evaluation.full();
	}

	private Decision checkRecipe(MenuOptionClicked event, String kind, String name, String target)
	{
		RecipeRuleCatalog.Rule rule = recipes.find(kind, name, target);
		if (rule == null)
		{
			return Decision.NOT_APPLICABLE;
		}
		SkillModes.Requirements mode;
		boolean skipTinderbox = false;
		switch (rule.category())
		{
			case "firemaking":
				if (config.firemaking() == SkillModes.Firemaking.OFF
					|| (rule.isColouredEventLog() && !config.eventLogs())) return Decision.ALLOWED;
				mode = SkillModes.Requirements.INPUTS;
				skipTinderbox = config.firemaking() == SkillModes.Firemaking.LOGS;
				break;
			case "smithing-smelt": mode = config.smelting(); break;
			case "smithing-forge": mode = config.smithing(); break;
			case "crafting": mode = config.crafting(); break;
			case "enchanting": mode = config.enchanting(); break;
			case "fletching": mode = config.fletching(); break;
			case "herblore": mode = config.herblore(); break;
			default: mode = SkillModes.Requirements.BOTH;
		}
		if (mode == SkillModes.Requirements.OFF)
		{
			return Decision.ALLOWED;
		}
		List<String> missing = rule.missing(collection.cards(), mode.inputs(), mode.output(), skipTinderbox);
		if (rule.isCrushable() && config.crushedGem() && !collection.cards().contains("crushed gem"))
		{
			missing.add("Crushed gem");
		}
		return consumeIfMissing(event, missing);
	}

	private Decision consumeIfMissing(MenuOptionClicked event, List<String> missing)
	{
		if (missing.isEmpty())
		{
			return Decision.ALLOWED;
		}
		event.consume();
		feedback.missing(missing);
		return Decision.BLOCKED;
	}

	private List<String> missingCards(List<String> cards)
	{
		Set<String> owned = collection.cards();
		List<String> missing = new ArrayList<>();
		for (String card : cards)
		{
			if (card != null && !owned.contains(card.toLowerCase(Locale.ROOT)))
			{
				missing.add(card);
			}
		}
		return missing;
	}

	private String itemName(MenuOptionClicked event, MenuEntry entry)
	{
		if (entry.isItemOp() && event.getItemId() > 0)
		{
			ItemComposition item = itemManager.getItemComposition(itemManager.canonicalize(event.getItemId()));
			return item == null ? "" : item.getName();
		}
		return clean(event.getMenuTarget());
	}

	private boolean selectedWidgetIsSpell()
	{
		return client.isWidgetSelected() && client.getSelectedWidget() != null
			&& client.getSelectedWidget().getItemId() <= 0;
	}

	private static boolean isMakeVerb(String option)
	{
		for (String verb : MAKE_VERBS)
		{
			if (option.startsWith(verb)) return true;
		}
		return false;
	}

	private static String[] splitTarget(String target)
	{
		String clean = Text.removeTags(target == null ? "" : target);
		int split = clean.lastIndexOf(SEPARATOR);
		return split < 0 ? null : new String[]{clean.substring(0, split).trim(), clean.substring(split + SEPARATOR.length()).trim()};
	}

	private static String npcName(NPC npc)
	{
		NPCComposition transformed = npc.getTransformedComposition();
		return transformed != null && transformed.getName() != null ? transformed.getName() : npc.getName();
	}

	private static String clean(String value)
	{
		return Text.removeTags(value == null ? "" : value).trim().toLowerCase(Locale.ROOT);
	}

	private static final class Evaluation
	{
		private final Set<String> excludedRoles;
		private final boolean requireAll;

		private Evaluation(Set<String> excludedRoles, boolean requireAll)
		{
			this.excludedRoles = excludedRoles;
			this.requireAll = requireAll;
		}

		private static Evaluation full()
		{
			return new Evaluation(Collections.emptySet(), false);
		}

		private static Evaluation excluding(String... roles)
		{
			return new Evaluation(new HashSet<>(Arrays.asList(roles)), false);
		}
	}
}

package com.groupmantcg;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

class StoredTcgState
{
	long openedPacks;
	List<CardEntry> cardEntries;
	List<CardInstance> cardInstances;

	boolean hasCollectionData()
	{
		return cardEntries != null || cardInstances != null;
	}

	List<CardInstance> expandedCardInstances()
	{
		if (cardEntries == null || cardEntries.isEmpty())
		{
			return cardInstances == null ? Collections.emptyList() : cardInstances;
		}

		List<CardInstance> expanded = new ArrayList<>();
		Map<String, Integer> occurrences = new HashMap<>();
		for (CardEntry entry : cardEntries)
		{
			if (entry == null || entry.cardName == null || entry.cardName.trim().isEmpty()
				|| entry.variants == null)
			{
				continue;
			}
			String cardName = entry.cardName.trim();
			for (CardVariant variant : entry.variants)
			{
				if (variant == null)
				{
					continue;
				}
				int quantity = variant.quantity == null ? 1 : Math.max(0, variant.quantity);
				String pulledBy = variant.pulledBy == null ? "" : variant.pulledBy.trim();
				long pulledAt = variant.pulledAt == null ? 0L : Math.max(0L, variant.pulledAt);
				boolean foil = Boolean.TRUE.equals(variant.foil);
				String signature = cardName + "\u0000" + foil + "\u0000" + pulledBy + "\u0000" + pulledAt;
				for (int copy = 0; copy < quantity; copy++)
				{
					int occurrence = occurrences.merge(signature, 1, Integer::sum);
					CardInstance instance = new CardInstance();
					instance.id = UUID.nameUUIDFromBytes((signature + "\u0000" + occurrence)
						.getBytes(StandardCharsets.UTF_8)).toString();
					instance.cardName = cardName;
					instance.foil = foil;
					instance.pulledBy = pulledBy;
					instance.pulledAt = pulledAt;
					expanded.add(instance);
				}
			}
		}
		return expanded;
	}

	static class CardEntry
	{
		String cardName;
		List<CardVariant> variants;
	}

	static class CardVariant
	{
		Boolean foil;
		String pulledBy;
		Long pulledAt;
		Integer quantity;
	}

	static class CardInstance
	{
		String id;
		String cardName;
		boolean foil;
		String pulledBy;
		long pulledAt;
	}
}

package com.groupmantcg;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.zip.GZIPInputStream;

/** Decodes OSRS TCG's public RLTCG_v2 profile-storage representation. */
final class StoredTcgStateDecoder
{
	private static final String PREFIX = "RLTCG_v2:";
	private static final byte[] XOR_SALT = {
		0x52, 0x4c, 0x54, 0x43, 0x47, 0x7c, 0x6f, 0x73,
		0x72, 0x73, 0x2d, 0x74, 0x63, 0x67, 0x21
	};

	private StoredTcgStateDecoder()
	{
	}

	static String decode(String stored)
	{
		if (stored == null || !stored.startsWith(PREFIX))
		{
			return "";
		}
		try
		{
			byte[] compressed = Base64.getDecoder().decode(stored.substring(PREFIX.length()));
			for (int i = 0; i < compressed.length; i++)
			{
				compressed[i] ^= XOR_SALT[i % XOR_SALT.length];
			}
			try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(compressed)))
			{
				return new String(gzip.readAllBytes(), StandardCharsets.UTF_8);
			}
		}
		catch (IllegalArgumentException | IOException ex)
		{
			return "";
		}
	}
}

package com.groupmantcg;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
class TopTrumpsOverlay extends Overlay
{
	private static final int WIDTH = 400;
	private static final int HEIGHT = 304;
	private static final int CARD_WIDTH = 150;
	private static final int CARD_HEIGHT = 217;
	private static final int CARD_Y = 50;
	private static final Color PANEL = new Color(16, 19, 23, 242);
	private static final Color BRONZE = new Color(184, 115, 51);
	private static final Color WINNER = new Color(75, 184, 100);
	private static final Color LOSER = new Color(113, 116, 122);

	private final TopTrumpsService service;
	private final CardArtService art;

	@Inject
	TopTrumpsOverlay(TopTrumpsService service, CardArtService art)
	{
		this.service = service;
		this.art = art;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		TopTrumpsService.ResultView result = service.currentResult();
		if (result == null)
		{
			return null;
		}

		Graphics2D copy = (Graphics2D) graphics.create();
		try
		{
			copy.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			copy.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			copy.setColor(PANEL);
			copy.fillRoundRect(0, 0, WIDTH, HEIGHT, 12, 12);
			copy.setColor(BRONZE);
			copy.setStroke(new BasicStroke(1.5f));
			copy.drawRoundRect(0, 0, WIDTH - 1, HEIGHT - 1, 12, 12);

			drawHeader(copy, result);
			drawCard(copy, 20, CARD_Y, result.challengerName(), result.challengerCard(), result.winner() == 0);
			drawCard(copy, WIDTH - 20 - CARD_WIDTH, CARD_Y, result.challengedName(),
				result.challengedCard(), result.winner() == 1);
			drawVersus(copy);
			drawWinner(copy, result);
		}
		finally
		{
			copy.dispose();
		}
		return new Dimension(WIDTH, HEIGHT);
	}

	private static void drawHeader(Graphics2D graphics, TopTrumpsService.ResultView result)
	{
		graphics.setFont(FontManager.getRunescapeBoldFont());
		String title = "OSRS TCG  •  TOP TRUMPS";
		FontMetrics metrics = graphics.getFontMetrics();
		int x = Math.max(8, (WIDTH - metrics.stringWidth(title)) / 2);
		graphics.setColor(Color.BLACK);
		graphics.drawString(title, x + 1, 21);
		graphics.setColor(Color.WHITE);
		graphics.drawString(title, x, 20);
	}

	private void drawCard(Graphics2D graphics, int x, int y, String player,
		CardVisualCatalog.CardVisual card, boolean winner)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		drawCentered(graphics, player, x, y - 7, CARD_WIDTH, winner ? WINNER : Color.LIGHT_GRAY);
		OsrsTcgCardRenderer.drawCardFace(graphics, new Rectangle(x, y, CARD_WIDTH, CARD_HEIGHT), card,
			false, card.rarityColor(), art.getCached(card.displayName()));
		graphics.setColor(winner ? WINNER : LOSER);
		graphics.setStroke(new BasicStroke(winner ? 2.4f : 1.2f));
		graphics.drawRoundRect(x - 3, y - 3, CARD_WIDTH + 5, CARD_HEIGHT + 5, 11, 11);
	}

	private static void drawVersus(Graphics2D graphics)
	{
		graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont(17f));
		drawCentered(graphics, "VS", 0, 160, WIDTH, BRONZE);
	}

	private static void drawWinner(Graphics2D graphics, TopTrumpsService.ResultView result)
	{
		graphics.setFont(FontManager.getRunescapeBoldFont());
		String text = result.winnerName() + " WINS" + (result.tieBreak() ? " • TIE-BREAK" : "");
		drawCentered(graphics, text, 0, HEIGHT - 9, WIDTH, WINNER);
	}

	private static void drawCentered(Graphics2D graphics, String text, int x, int baseline, int width, Color color)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		String shown = text == null ? "" : text;
		int textX = x + (width - metrics.stringWidth(shown)) / 2;
		graphics.setColor(new Color(0, 0, 0, 190));
		graphics.drawString(shown, textX + 1, baseline + 1);
		graphics.setColor(color);
		graphics.drawString(shown, textX, baseline);
	}

}

package com.groupmantcg;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Random;
import java.util.Set;

/** Pure card draw and winner rules shared by both duel participants. */
final class TopTrumpsRules
{
	private TopTrumpsRules()
	{
	}

	static Match draw(Set<String> collection, CardVisualCatalog catalog, Random random, String challengeId)
	{
		List<CardVisualCatalog.CardVisual> pool = new ArrayList<>();
		for (String cardName : collection)
		{
			CardVisualCatalog.CardVisual card = catalog.find(cardName);
			if (card != null)
			{
				pool.add(card);
			}
		}
		pool.sort(Comparator.comparing(CardVisualCatalog.CardVisual::displayName,
			String.CASE_INSENSITIVE_ORDER));
		if (pool.size() < 2)
		{
			return null;
		}

		CardVisualCatalog.CardVisual challenger = pool.remove(random.nextInt(pool.size()));
		CardVisualCatalog.CardVisual challenged = pool.get(random.nextInt(pool.size()));
		int comparison = Double.compare(challenger.score(), challenged.score());
		boolean tieBreak = comparison == 0;
		int winner = comparison > 0 ? 0 : comparison < 0 ? 1
			: deterministicTieWinner(challengeId, challenger.displayName(), challenged.displayName());
		return new Match(challenger, challenged, winner, tieBreak);
	}

	static int winner(double challengerScore, double challengedScore, String challengeId,
		String challengerCard, String challengedCard)
	{
		int comparison = Double.compare(challengerScore, challengedScore);
		return comparison > 0 ? 0 : comparison < 0 ? 1
			: deterministicTieWinner(challengeId, challengerCard, challengedCard);
	}

	private static int deterministicTieWinner(String challengeId, String challengerCard, String challengedCard)
	{
		String seed = String.valueOf(challengeId) + '\n' + challengerCard + '\n' + challengedCard;
		return Math.floorMod(seed.hashCode(), 2);
	}

	static final class Match
	{
		private final CardVisualCatalog.CardVisual challengerCard;
		private final CardVisualCatalog.CardVisual challengedCard;
		private final int winner;
		private final boolean tieBreak;

		private Match(CardVisualCatalog.CardVisual challengerCard,
			CardVisualCatalog.CardVisual challengedCard, int winner, boolean tieBreak)
		{
			this.challengerCard = challengerCard;
			this.challengedCard = challengedCard;
			this.winner = winner;
			this.tieBreak = tieBreak;
		}

		CardVisualCatalog.CardVisual challengerCard() { return challengerCard; }
		CardVisualCatalog.CardVisual challengedCard() { return challengedCard; }
		int winner() { return winner; }
		boolean tieBreak() { return tieBreak; }
	}
}

package com.groupmantcg;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;

/** Handles Top Trumps challenges and results between server members. */
@Singleton
class TopTrumpsService
{
	static final String MENU_OPTION = "Top Trumps";
	private static final int MAX_SEEN_EVENTS = 128;
	private static final long MAX_EVENT_AGE_MILLIS = 120_000L;

	private final Client client;
	private final ClientThread clientThread;
	private final GroupmanTcgConfig config;
	private final HostedSyncService hosted;
	private final CardVisualCatalog cards;
	private final CardArtService cardArt;
	private final ChatboxPanelManager chatbox;
	private final Set<String> seenEvents = new LinkedHashSet<>();

	private boolean started;
	private ResultView activeResult;

	@Inject
	TopTrumpsService(Client client, ClientThread clientThread, GroupmanTcgConfig config,
		HostedSyncService hosted, CardVisualCatalog cards, CardArtService cardArt,
		ChatboxPanelManager chatbox)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.hosted = hosted;
		this.cards = cards;
		this.cardArt = cardArt;
		this.chatbox = chatbox;
	}

	void start()
	{
		started = true;
	}

	synchronized void stop()
	{
		started = false;
		seenEvents.clear();
		activeResult = null;
	}

	boolean canChallenge(String playerName)
	{
		if (!started || !config.topTrumpsEnabled())
		{
			return false;
		}
		HostedSyncStatus.Member member = hosted.memberByPlayerName(playerName);
		return member != null && hosted.canChallenge(member.id());
	}

	void challenge(String playerName)
	{
		HostedSyncStatus.Member member = hosted.memberByPlayerName(playerName);
		if (member == null)
		{
			gameMessage("That player is not an approved member of your Group TCG server.");
			return;
		}
		challengeMember(member);
	}

	void challengeMember(HostedSyncStatus.Member member)
	{
		if (!started || !config.topTrumpsEnabled() || member == null || !hosted.canChallenge(member.id()))
		{
			gameMessage("That player is not available for a server Top Trumps challenge.");
			return;
		}
		hosted.challengeMember(member.id(), error -> clientThread.invokeLater(() ->
		{
			if (error == null)
			{
				gameMessage("Top Trumps challenge sent to " + displayName(member) + ".");
			}
			else
			{
				gameMessage(error);
			}
		}));
	}

	synchronized void hostedEvent(HostedApiClient.TopTrumpsEvent event)
	{
		if (!started || !config.topTrumpsEnabled() || event == null || event.challengeId == null
			|| event.type == null || event.challenger == null || event.challenged == null
			|| event.createdAt < System.currentTimeMillis() - MAX_EVENT_AGE_MILLIS
			|| !rememberEvent(event.type + ':' + event.challengeId))
		{
			return;
		}
		String localMemberId = hosted.status().memberId();
		if (localMemberId.isEmpty())
		{
			return;
		}
		switch (event.type)
		{
			case "challenge":
				if (localMemberId.equals(event.challenged.id)
					&& event.expiresAt >= System.currentTimeMillis())
				{
					showChallenge(event);
				}
				break;
			case "declined":
				if (localMemberId.equals(event.challenger.id))
				{
					gameMessage(displayName(event.challenged) + " declined your Top Trumps challenge.");
				}
				break;
			case "result":
				if (localMemberId.equals(event.challenger.id) || localMemberId.equals(event.challenged.id))
				{
					showResult(event);
				}
				break;
			default:
				break;
		}
	}

	private void showChallenge(HostedApiClient.TopTrumpsEvent event)
	{
		String challenger = displayName(event.challenger);
		chatbox.openTextMenuInput("Top Trumps challenge from " + challenger)
			.option("Accept", () -> respond(event, true))
			.option("Decline", () -> respond(event, false))
			.build();
		gameMessage(challenger + " challenged you to Top Trumps.");
	}

	private void respond(HostedApiClient.TopTrumpsEvent event, boolean accepted)
	{
		if (event.expiresAt < System.currentTimeMillis())
		{
			gameMessage("That Top Trumps challenge has expired.");
			return;
		}
		hosted.respondTopTrumps(event.challengeId, accepted, error -> clientThread.invokeLater(() ->
		{
			if (error == null)
			{
				gameMessage(accepted ? "Top Trumps challenge accepted." : "Top Trumps challenge declined.");
			}
			else
			{
				gameMessage(error);
			}
		}));
	}

	private void showResult(HostedApiClient.TopTrumpsEvent event)
	{
		if (event.challengerCard == null || event.challengedCard == null)
		{
			return;
		}
		CardVisualCatalog.CardVisual challengerCard = cards.find(event.challengerCard);
		CardVisualCatalog.CardVisual challengedCard = cards.find(event.challengedCard);
		if (challengerCard == null || challengedCard == null)
		{
			return;
		}
		int winner = TopTrumpsRules.winner(challengerCard.score(), challengedCard.score(),
			event.challengeId, challengerCard.displayName(), challengedCard.displayName());
		boolean tieBreak = Double.compare(challengerCard.score(), challengedCard.score()) == 0;
		long duration = Math.max(5, Math.min(20, config.topTrumpsDuration())) * 1_000L;
		activeResult = new ResultView(event.challengeId, displayName(event.challenger),
			displayName(event.challenged), challengerCard, challengedCard, winner, tieBreak,
			System.currentTimeMillis() + duration);
		cardArt.preload(Arrays.asList(challengerCard.displayName(), challengedCard.displayName()));
		gameMessage(activeResult.winnerName() + " wins Top Trumps" + (tieBreak ? " on the tie-break" : "") + "!");
	}

	synchronized void onTick()
	{
		if (activeResult != null && activeResult.expiresAt < System.currentTimeMillis())
		{
			activeResult = null;
		}
	}

	synchronized ResultView currentResult()
	{
		if (!config.topTrumpsEnabled())
		{
			activeResult = null;
			return null;
		}
		onTick();
		return activeResult;
	}

	private boolean rememberEvent(String eventKey)
	{
		if (!seenEvents.add(eventKey))
		{
			return false;
		}
		while (seenEvents.size() > MAX_SEEN_EVENTS)
		{
			seenEvents.remove(seenEvents.iterator().next());
		}
		return true;
	}

	private void gameMessage(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[Group TCG] " + message, null);
	}

	private static String displayName(HostedSyncStatus.Member member)
	{
		return safeName(member.playerName().isEmpty() ? member.label() : member.playerName());
	}

	private static String displayName(HostedApiClient.MemberRef member)
	{
		return safeName(member.playerName == null || member.playerName.trim().isEmpty()
			? member.label : member.playerName);
	}

	private static String safeName(String value)
	{
		if (value == null)
		{
			return "Server member";
		}
		String clean = value.trim();
		return clean.isEmpty() ? "Server member" : clean.substring(0, Math.min(16, clean.length()));
	}

	static final class ResultView
	{
		private final String challengeId;
		private final String challengerName;
		private final String challengedName;
		private final CardVisualCatalog.CardVisual challengerCard;
		private final CardVisualCatalog.CardVisual challengedCard;
		private final int winner;
		private final boolean tieBreak;
		private final long expiresAt;

		private ResultView(String challengeId, String challengerName, String challengedName,
			CardVisualCatalog.CardVisual challengerCard, CardVisualCatalog.CardVisual challengedCard,
			int winner, boolean tieBreak, long expiresAt)
		{
			this.challengeId = challengeId;
			this.challengerName = challengerName;
			this.challengedName = challengedName;
			this.challengerCard = challengerCard;
			this.challengedCard = challengedCard;
			this.winner = winner;
			this.tieBreak = tieBreak;
			this.expiresAt = expiresAt;
		}

		String challengeId() { return challengeId; }
		String challengerName() { return challengerName; }
		String challengedName() { return challengedName; }
		CardVisualCatalog.CardVisual challengerCard() { return challengerCard; }
		CardVisualCatalog.CardVisual challengedCard() { return challengedCard; }
		int winner() { return winner; }
		boolean tieBreak() { return tieBreak; }
		long expiresAt() { return expiresAt; }
		String winnerName() { return winner == 0 ? challengerName : challengedName; }
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
