	public void remoteRevealWaitsFifteenSecondsAfterServerReceipt()
	{
		long openedAt = 10_000L;
		long receivedAt = 12_000L;
		assertEquals(27_000L, GroupPackRevealService.remoteRevealNotBefore(
			openedAt, receivedAt, 13_000L));
