package com.groupmantcg;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OsrsTcgInteropServiceTest
{
	@Test
	public void acceptsV1CollectionAndFoilPayload()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", Arrays.asList(" Abyssal whip ", "Dragon scimitar"));
		data.put("ownedFoilNames", Collections.singletonList("ABYSSAL WHIP"));

		assertTrue(service.accept(message(OsrsTcgInteropService.CHANGED, data)));
		OsrsTcgInteropService.Snapshot snapshot = service.snapshot();
		assertTrue(snapshot.available());
		assertEquals("Abyssal whip", snapshot.ownedNames().get("abyssal whip"));
		assertTrue(snapshot.foilNames().contains("abyssal whip"));
		assertTrue(snapshot.foilDataAvailable());
	}

	@Test
	public void ignoresEmptyStartupReplyButAcceptsAuthoritativeEmptyChange()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", Collections.emptyList());
		data.put("ownedFoilNames", Collections.emptyList());

		assertFalse(service.accept(message(OsrsTcgInteropService.REPLY, data)));
		assertFalse(service.snapshot().available());
		assertTrue(service.accept(message(OsrsTcgInteropService.CHANGED, data)));
		assertTrue(service.snapshot().available());
		assertTrue(service.snapshot().ownedNames().isEmpty());
	}

	@Test
	public void emptyReplyCannotReplaceLoadedCollection()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> loaded = new HashMap<>();
		loaded.put("ownedNames", Collections.singletonList("Zulrah"));
		assertTrue(service.accept(message(OsrsTcgInteropService.CHANGED, loaded)));

		Map<String, Object> empty = new HashMap<>();
		empty.put("ownedNames", Collections.emptyList());
		assertFalse(service.accept(message(OsrsTcgInteropService.REPLY, empty)));
		assertTrue(service.snapshot().ownedNames().containsKey("zulrah"));
	}

	@Test
	public void cloudReadyEmptyReplyIsAuthoritative()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", Collections.emptyList());
		data.put("ownedFoilNames", Collections.emptyList());
		data.put("groupKey", "connected-group");

		assertTrue(service.accept(message(OsrsTcgInteropService.REPLY, data)));
		assertTrue(service.snapshot().available());
		assertTrue(service.snapshot().ownedNames().isEmpty());
	}

	@Test
	public void rejectsMalformedCollectionPayload()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> data = new HashMap<>();
		data.put("ownedNames", Arrays.asList("Valid", 42));
		assertFalse(service.accept(message(OsrsTcgInteropService.CHANGED, data)));
		assertFalse(service.snapshot().available());
	}

	@Test
	public void infersOnePackFromCardsGainedAfterBaseline()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> baseline = new HashMap<>();
		baseline.put("ownedNames", Collections.singletonList("Zulrah"));
		baseline.put("ownedFoilNames", Collections.emptyList());
		assertTrue(service.accept(message(OsrsTcgInteropService.REPLY, baseline)));
		assertTrue(service.drainInferredPack() == null);

		Map<String, Object> changed = new HashMap<>();
		changed.put("ownedNames", Arrays.asList("Zulrah", "Abyssal whip", "Dragon scimitar"));
		changed.put("ownedFoilNames", Collections.singletonList("Dragon scimitar"));
		assertTrue(service.accept(message(OsrsTcgInteropService.CHANGED, changed)));

		OsrsTcgInteropService.InferredPack pack = service.drainInferredPack();
		assertEquals(2, pack.cards().size());
		assertEquals("Abyssal whip", pack.cards().get(0).displayName());
		assertFalse(pack.cards().get(0).foil());
		assertEquals("Dragon scimitar", pack.cards().get(1).displayName());
		assertTrue(pack.cards().get(1).foil());
		assertTrue(service.drainInferredPack() == null);
	}

	@Test
	public void doesNotTreatInitialCloudLoadAsPack()
	{
		OsrsTcgInteropService service = startedService();
		Map<String, Object> changed = new HashMap<>();
		changed.put("ownedNames", Arrays.asList("Zulrah", "Vorkath"));
		changed.put("ownedFoilNames", Collections.emptyList());
		assertTrue(service.accept(message(OsrsTcgInteropService.CHANGED, changed)));
		assertTrue(service.drainInferredPack() == null);
	}

	private static OsrsTcgInteropService startedService()
	{
		OsrsTcgInteropService service = new OsrsTcgInteropService(null);
		service.start();
		return service;
	}

	private static PluginMessage message(String name, Map<String, Object> data)
	{
		return new PluginMessage(OsrsTcgInteropService.NAMESPACE, name, data);
	}
}

