package com.groupmantcg;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class SkillRuleCatalogTest
{
	private final InteractionRuleCatalog interactions = new InteractionRuleCatalog(new Gson());
	private final RecipeRuleCatalog recipes = new RecipeRuleCatalog(new Gson());

	@Test
	public void woodcuttingRequiresTheYieldCard()
	{
		InteractionRuleCatalog.Rule rule = interactions.find("object", "Dead tree", "Chop down");
		assertNotNull(rule);
		assertEquals("woodcutting", rule.category());
		assertEquals(Collections.singletonList("Logs"),
			rule.missing(Collections.emptySet(), Collections.emptySet(), false));
		assertTrue(rule.missing(Collections.singleton("logs"), Collections.emptySet(), false).isEmpty());
	}

	@Test
	public void fishingSupportsAnyAndAllDifficulty()
	{
		InteractionRuleCatalog.Rule rule = interactions.find("npc", "Fishing spot", "Bait");
		Set<String> oneFish = Collections.singleton("raw sardine");

		assertTrue(rule.missing(oneFish, Collections.emptySet(), false).isEmpty());
		assertFalse(rule.missing(oneFish, Collections.emptySet(), true).isEmpty());
	}

	@Test
	public void roleExclusionsImplementFarmingAndSlayerModes()
	{
		InteractionRuleCatalog.Rule farming = interactions.find(
			"item-on-object", "Asgarnian seed", "Hops patch");
		Set<String> toolsAndSeed = new HashSet<>();
		toolsAndSeed.add("seed dibber");
		toolsAndSeed.add("asgarnian seed");
		assertTrue(farming.missing(toolsAndSeed, Collections.singleton("produce"), false).isEmpty());
		assertFalse(farming.missing(toolsAndSeed, Collections.emptySet(), false).isEmpty());

		InteractionRuleCatalog.Rule slayer = interactions.find("npc", "Achtryn", "Assignment");
		Set<String> masterOnly = Collections.singleton("achtryn");
		Set<String> excluded = new HashSet<>();
		excluded.add("monsters");
		excluded.add("superiors");
		assertTrue(slayer.missing(masterOnly, excluded, false).isEmpty());
		assertFalse(slayer.missing(masterOnly, Collections.emptySet(), false).isEmpty());
	}

	@Test
	public void recipeScopesAndTinderboxExceptionAreEvaluated()
	{
		RecipeRuleCatalog.Rule smelting = recipes.find("item-on-object", "Copper ore", "Furnace");
		assertNotNull(smelting);
		Set<String> ores = new HashSet<>();
		ores.add("copper ore");
		ores.add("tin ore");
		assertTrue(smelting.missing(ores, true, false, false).isEmpty());
		assertEquals(Collections.singletonList("Bronze bar"), smelting.missing(ores, false, true, false));

		RecipeRuleCatalog.Rule firemaking = recipes.find("item-on-item", "Tinderbox", "Oak logs");
		List<String> strict = firemaking.missing(Collections.singleton("oak logs"), true, false, false);
		assertTrue(strict.contains("Tinderbox"));
		assertTrue(firemaking.missing(Collections.singleton("oak logs"), true, false, true).isEmpty());
	}

	@Test
	public void allSpecialistDatasetsLoad()
	{
		assertTrue(interactions.size() > 400);
		assertTrue(recipes.size() > 300);
		assertEquals(45, interactions.masterFarmerSeeds().size());
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.HashSet;
import java.util.List;
import java.util.zip.GZIPOutputStream;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StoredTcgStateDecoderTest
{
	private static final byte[] SALT = {
		0x52, 0x4c, 0x54, 0x43, 0x47, 0x7c, 0x6f, 0x73,
		0x72, 0x73, 0x2d, 0x74, 0x63, 0x67, 0x21
	};

	@Test
	public void decodesVersionTwoState() throws Exception
	{
		String json = "{\"cardInstances\":[{\"cardName\":\"Goblin\"}]}";
		assertEquals(json, StoredTcgStateDecoder.decode(encode(json)));
	}

	@Test
	public void rejectsMissingOrMalformedState()
	{
		assertEquals("", StoredTcgStateDecoder.decode(null));
		assertEquals("", StoredTcgStateDecoder.decode("wrong-format"));
		assertEquals("", StoredTcgStateDecoder.decode("RLTCG_v2:not-base64"));
	}

	@Test
	public void expandsCurrentGroupedCardEntriesWithStableUniqueIds() throws Exception
	{
		String goblinEntry = "{\"cardName\":\"Goblin\",\"variants\":["
			+ "{\"pulledBy\":\"Player\",\"pulledAt\":1000},"
			+ "{\"foil\":true,\"pulledBy\":\"Player\",\"pulledAt\":2000},"
			+ "{\"quantity\":2,\"pulledBy\":\"Player\",\"pulledAt\":3000}]}";
		String json = "{\"openedPacks\":12,\"cardEntries\":[" + goblinEntry + "]}";
		StoredTcgState state = new Gson().fromJson(StoredTcgStateDecoder.decode(encode(json)),
			StoredTcgState.class);
		List<StoredTcgState.CardInstance> cards = state.expandedCardInstances();

		assertTrue(state.hasCollectionData());
		assertEquals(12L, state.openedPacks);
		assertEquals(4, cards.size());
		assertFalse(cards.get(0).foil);
		assertTrue(cards.get(1).foil);
		assertEquals(4, new HashSet<>(List.of(cards.get(0).id, cards.get(1).id,
			cards.get(2).id, cards.get(3).id)).size());

		StoredTcgState reordered = new Gson().fromJson("{\"cardEntries\":["
			+ "{\"cardName\":\"Abyssal demon\",\"variants\":[{}]}," + goblinEntry + "]}",
			StoredTcgState.class);
		assertEquals(cards.get(0).id, reordered.expandedCardInstances().get(1).id);
	}

	@Test
	public void retainsLegacyCardInstancesCompatibility()
	{
		StoredTcgState state = new Gson().fromJson("{\"cardInstances\":["
			+ "{\"id\":\"legacy-1\",\"cardName\":\"Cow\",\"foil\":true}]}", StoredTcgState.class);
		assertTrue(state.hasCollectionData());
		assertEquals("legacy-1", state.expandedCardInstances().get(0).id);
		assertTrue(state.expandedCardInstances().get(0).foil);
	}

	private static String encode(String json) throws Exception
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(output))
		{
			gzip.write(json.getBytes(StandardCharsets.UTF_8));
		}
		byte[] bytes = output.toByteArray();
		for (int i = 0; i < bytes.length; i++)
		{
			bytes[i] ^= SALT[i % SALT.length];
		}
		return "RLTCG_v2:" + Base64.getEncoder().encodeToString(bytes);
	}
}

package com.groupmantcg;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TopTrumpsRulesTest
{
	@Test
	public void mirrorsOsrsTcgPowerFormula()
	{
		assertEquals(6d, CardVisualCatalog.calculateScore(null, 2, null, true), 0.001d);
		assertEquals(100d, CardVisualCatalog.calculateScore(100L, 2, null, true), 0.001d);
		assertEquals(500d, CardVisualCatalog.calculateScore(100L, 2, 500L, true), 0.001d);
	}

	@Test
	public void drawsTwoDifferentSharedCardsAndFindsWinner()
	{
		CardVisualCatalog catalog = new CardVisualCatalog(new Gson());
		TopTrumpsRules.Match match = TopTrumpsRules.draw(
			new HashSet<>(Arrays.asList("goblin", "great olm")), catalog, new Random(7L), "duel-1");

		assertNotNull(match);
		assertFalse(match.challengerCard().displayName().equals(match.challengedCard().displayName()));
		String winner = match.winner() == 0
			? match.challengerCard().displayName() : match.challengedCard().displayName();
		assertEquals("Great Olm", winner);
		assertFalse(match.tieBreak());
		assertTrue(catalog.find("Great Olm").power() > catalog.find("Goblin").power());
	}

	@Test
	public void equalPowerAlwaysProducesTheSameTieWinner()
	{
		int first = TopTrumpsRules.winner(1d, 1d, "same-duel", "Card A", "Card B");
		int second = TopTrumpsRules.winner(1d, 1d, "same-duel", "Card A", "Card B");
		assertEquals(first, second);
		assertTrue(first == 0 || first == 1);
	}
}
